comms.text:
@1 וַאֲמַר יְיָ לְמֹשֶׁה אֱמַר לְכַהֲנַיָא בְּנֵי אַהֲרֹן וְתֵימַר לְהוֹן עַל מִית לָא יִסְתָּאַב בְּעַמֵהּ:
@2 אֱלָהֵן לְקָרִיבֵהּ דְקָרִיב לֵהּ לְאִמֵהּ וְלַאֲבוּהִי וְלִבְרֵהּ וְלִבְרַתֵּהּ וְלַאֲחוּהִי:
@3 וְלַאֲחָתֵהּ בְּתֻלְתָּא דְקָרִיבָא לֵהּ דִי לָא הֲוַת לִגְבַר לַהּ יִסְתָּאָב:
@4 לָא יִסְתָּאַב רַבָּא בְעַמֵהּ לְאַחֲלוּתֵהּ:
@5 לָא יִמְרְטוּן מְרַט בְּרֵישְׁהוֹן וּפָאתָא דְדִקְנְהוֹן לָא יְגַלְחוּן וּבְבִשְׂרְהוֹן לָא יְחַבְּלוּן חִבּוּל:
@6 קַדִישִׁין יְהוֹן קֳדָם אֱלָהֲהוֹן וְלָא יְחַלוּן שְׁמָא דֶאֱלָהֲהוֹן אֲרֵי יָת קֻרְבָּנַיָא דַיְיָ קֻרְבַּן אֱלָהֲהוֹן אִנוּן מַקְרִיבִין וִיהוֹן קַדִישִׁין:
@7 אִתְּתָא מַטְעֲיָא וּמְחַלְלָא לָא יִסְבוּן וְאִתְּתָא דִמְתָרְכָא מִבַּעְלַהּ לָא יִסְבוּן אֲרֵי קַדִישׁ הוּא קֳדָם אֱלָהֵהּ:
@8 וּתְקַדְשִׁנֵהּ אֲרֵי יָת קֻרְבַּן אֱלָהָךְ הוּא מְקָרֵב קַדִישׁ יְהֵא לָךְ אֲרֵי קַדִישׁ אֲנָא יְיָ מְקַדִשְׁכוֹן:
@9 וּבַת גְבַר כָּהֵן אֲרֵי תִתְחַל לְמִטְעֵי מִקְדֻשַׁת אֲבוּהָ הִיא מִתַּחֲלָא בְּנוּרָא תִּתּוֹקָד:
@10 וְכַהֲנָא דְאִתְרַבָּא מֵאֲחוֹהִי דְיִתָּרִיק עַל רֵישֵׁהּ מִשְׁחָא דִרְבוּתָא וְדִי קָרִיב יָת קֻרְבָּנֵהּ לְמִלְבָּשׁ יָת לְבוּשַׁיָא יָת רֵישֵׁהּ לָא יְרַבֵּי פֵרוּעַ וּלְבוּשׁוֹהִי לָא יִבְזַע:
@11 וְעַל כָּל נַפְשַׁת מֵתָא לָא יֵיעוֹל לַאֲבוּהִי וּלְאִמֵהּ לָא יִסְתָּאָב:
@12 וּמִן מַקְדְשָׁא לָא יִפּוֹק וְלָא יַחֵל יָת מַקְדְשָׁא דֶאֱלָהֵהּ אֲרֵי כְּלִיל מְשַׁח רְבוּתָא דֶאֱלָהֵהּ עֲלוֹהִי אֲנָא יְיָ:
@13 וְהוּא אִתְּתָא בִבְתֻלְתָּהָא יִסָב:
@14 אַרְמְלָא וּמְתָרְכָא וְחַלִילָא מַטְעֲיָא יָת אִלֵין לָא יִסָב אֱלָהֵין בְּתֻלְתָּא מֵעַמֵהּ יִסַב אִתְּתָא:
@15 וְלָא יַחֵל זַרְעֵהּ בְּעַמֵהּ אֲרֵי אֲנָא יְיָ מְקַדְשֵׁהּ:
@16 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@17 מַלֵל עִם אַהֲרֹן לְמֵימָר גְבַר מִבְּנָיִךְ לְדָרֵיהוֹן דִי יְהֵּי בֵהּ מוּמָא לָא יִקְרַב לְקָרָבָא קֻרְבָּנָא קֳדָם אֱלָהֵהּ:
@18 אֲרֵי כָל גְבַר דִּי בֵהּ מוּמָא לָא יִקְרַב גְבַר עַוִיר אוֹ חֲגִיר אוֹ חָרִים אוֹ שָׂרִיע:
@19 אוֹ גְבַר דִי יְהֵי בֵהּ תְּבַר רַגְלָא אוֹ תְּבַר יְדָא:
@20 אוֹ גְבִין אוֹ דֻקָא אוֹ חִלִיז בְּעֵינֵהּ אוֹ גַרְבָן אוֹ חֲזָזָן אוֹ מְרִיס פַּחֲדִין:
@21 כָּל גְבַר דִי בֵהּ מוּמָא מִזַרְעָא דְאַהֲרֹן כַּהֲנָא לָא יִקְרַב לְקָרָבָא יָת קֻרְבָּנַיָא דַיְיָ מוּמָא בֵהּ יָת קֻרְבַּן אֱלָהֵהּ לָא יִקְרַב לְקָרָבָא:
@22 קֻרְבַּן אֱלָהֵהּ מִקֹדֶשׁ קוּדְשַׁיָא וּמִן קוּדְשַׁיָא יֵיכוּל:
@23 בְּרַם לְפָרֻכְתָּא לָא יֵיעוֹל וּלְמַדְבְּחָא לָא יִקְרַב אֲרֵי מוּמָא בֵהּ וְלָא יַחֵל יָת מַקְדְשַׁי אֲרֵי אֲנָא יְיָ מְקַדִשְׁהוֹן:
@24 וּמַלִיל מֹשֶׁה עִם אַהֲרֹן וְעִם בְּנוֹהִי וְעִם כָּל בְּנֵי יִשְׂרָאֵל:
@25 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@26 מַלֵיל עִם אַהֲרֹן וְעִם בְּנוֹהִי וְיִפָּרְשׁוּן מִקוּדְשַׁיָא דִבְנֵי יִשְׂרָאֵל וְלָא יְחַלוּן יָת שְׁמָא דְקוּדְשִׁי דִי אִנוּן מְקַדְשִׁין קֳדָמַי אֲנָא יְיָ:
@27 אֱמַר לְהוֹן לְדָרֵיכוֹן כָּל גְבַר דִי יִקְרַב מִכָּל בְּנֵיכוֹן לְקוּדְשַׁיָא דִי יְקַדְשׁוּן בְּנֵי יִשְׂרָאֵל קֳדָם יְיָ וְסֹאבְתֵיהּ עֲלוֹהִי וְיִשְׁתֵּיצֵי אֲנָשָׁא הַהִיא מִן קֳדָמַי אֲנָא יְיָ:
@28 גְבַר גְבַר מִזַרְעָא דְאַהֲרֹן וְהוּא סְגִיר אוֹ דָאִיב בְּקוּדְשַׁיָא לָא יֵיכוּל עַד דִי יִדְכֵּי וּדְיִקְרַב בְּכָל טְמֵא נַפְשָׁא אוֹ גְבַר דִי תִפּוֹק מִנֵהּ שִׁכְבַת זַרְעָא:
@29 אוֹ גְבַר דִי יִקְרַב בְּכָל רִחֲשָׁא דִי יִסְתָּאַב לֵהּ אוֹ בַאֲנָשָׁא דִי יִסְתָּאַב לֵהּ:לכָל סֹאבְתֵיהּ:
@30 אֱנַשׁ דִי יִקְרַב בֵּהּ וִיהֵי מְסָאָב עַד רַמְשָׁא וְלָא יֵיכוּל מִן קוּדְשַׁיָא אֱלָהֵן אַסְחֵי בִשׂרֵהּ בְּמַיָא:
@31 וּבְמֵעַל:שִׁמְשָׁא וְיִדְכֵּי וּבָתַר כֵּן יֵיכוּל מִן קוּדְשַׁיָא אֲרֵי לַחְמֵהּ הוּא:
@32 נְבִילָא וּתְבִירָא לָא יֵיכוּל לְאִסְתָּאָבָא בָהּ אֲנָא יְיָ:
@33 וְיִטְרוּן יָת מַטְּרַת מֵימְרִי וְלָא יְקַבְּלוּן עֲלוֹהִי חוֹבָא וִימוּתוּן בֵּהּ אֲרֵי יְחַלֻנֵהּ אֲנָא יְיָ מְקַדִשְׁהוֹן:
@34 וְכָל חִלוֹנַי לָא יֵיכוּל קוּדְשָׁא תּוֹתָבָא דְכַהֲנָא וַאֲגִירָא לָא יֵיכוּל קוּדְשָׁא:
@35 וְכָהֵן אֲרֵי יִקְנֵי נְפַשׁ קִנְיַן כַּסְפֵּהּ הוּא יֵיכוּל בֵּהּ וִילִיד בֵּיתֵהּ אִנוּן יֵיכְלוּן בְּלַחְמֵהּ:
@36 וּבַת כָּהֵן אֲרֵי תְהִי לִגְבַר חִלוֹנָי הִיא בְּאַפְרָשׁוּת קוּדְשַׁיָא לָא תֵיכוּל:
@37 וּבַת כָּהֵן אֲרֵי תְהֵי אַרְמְלָא וּמְתָרְכָא וּבַר לֵית לַהּ וּתְתוּב לְבֵית אֲבוּהָא כְּרַבְיוּתָהָא מִלַחְמָא דַאֲבוּהָא תֵּיכוּל וְכָל חִלוֹנַי לָא יֵיכוּל בֵּהּ:
@38 וּגְבַר אֲרֵי יֵיכוּל קוּדְשָׁא בְּשָׁלוּ וְיוֹסֵף חוּמְשֵׁהּ עֲלוֹהִי וְיִתֵּן לְכַהֲנָא יָת קוּדְשָׁא:
@39 וְלָא יְחַלוּן יָת קוּדְשַׁיָא דִבְנֵי יִשְׂרָאֵל יָת דִי יַפְרְשׁוּן קֳדָם יְיָ:
@40 וִיקַבְּלוּן עֲלֵיהוֹן עֲוָיָן וְחוֹבִין בְּמֵיכָלְהוֹן בְּסוֹאֲבָא יָת קוּדְשֵׁיהוֹן אֲרֵי אֲנָא יְיָ מְקַדִשְׁהוֹן:
@41 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@42 מַלֵל עִם אַהֲרֹן וְעִם בְּנוֹהִי וְעִם כָּל בְּנֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן גְבַר גְבַר מִבֵּית יִשְׂרָאֵל וּמִן גִיוֹרָא בְּיִשְׂרָאֵל דִי יְקָרֵב קֻרְבָּנֵהּ לְכָל נִדְרֵיהוֹן וּלְכָל נִדְבָתְהוֹן דִי יְקָרְבוּן קֳדָם יְיָ לַעֲלָתָא:
@43 לְרַעֲוָא לְכוֹן שְׁלִים דְכוּרָא בְּתוֹרֵי בְּאִמְרַיָא וּבְעִזַיָא:
@44 כֹּל דִי בֵהּ מוּמָא לָא תְקָרְבוּן אֲרֵי לָא לְרַעֲוָא יְהֵי לְכוֹן:
@45 וּגְבַר אֲרֵי יְקָרֵב נִכְסַת קוּדְשַׁיָא קֳדָם יְיָ לְפָרָשָׁא נִדְרָא אוֹ לִנְדַבְתָּא בְּתוֹרֵי אוֹ בְעָנָא שְׁלִים יְהֵי לְרַעֲוָא כָּל מוּמָא לָא יְהֵי בֵהּ:
@46 עַוִיר אוֹ תְבִיר אוֹ פְסִיק אוֹ יַבְּלָן אוֹ גַרְבָן אוֹ חֲזָזָן לָא תְקָרְבוּן אִלֵין קֳדָם יְיָ וְקֻרְבָּנָא לָא תִתְּנוּן מִנְהוֹן עַל מַדְבְּחָא קֳדָם יְיָ:
@47 וְתוֹר וְאִמַר יַתִּיר וְחַסִיר נְדַבְתָּא תַּעְבֵּד יָתֵהּ וּלְנִדְרָא לָא יְהֵי לְרַעֲוָא:
@48 וְדִי מְרִיס וְדִי רְסִיס וְדִי שְׁלִיף וְדִי גְזִיר לָא תְקָרְבוּן קֳדָם יְיָ וּבְאַרְעֲכוֹן לָא תַעְבְּדוּן:
@49 וּמִן בַּר עַמְמִין לָא תְקַרְבוּן יָת קֻרְבַּן אֱלָהֲכוֹן מִכָּל אִלֵין אֲרֵי חִבּוּלְהוֹן בְּהוֹן מוּמָא בְהוֹן לָא לְרַעֲוָא יְהוֹן לְכוֹן:
@50 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@51 תּוֹר אוֹ אִמָר אוֹ עִזָא אֲרֵי יִתְיְלִיד וִיהֵי שִׁבְעָא יוֹמִין בָּתַר אִמֵהּ וּמִיוֹמָא תְמִינָאָה וּלְהַלָא יִתִּרְעִי לְקָרָבָא קֻרְבָּנָא קֳדָם יְיָ:
@52 וְתוֹרְתָּא אוֹ שֵׂיתָא לֵהּ וְלִבְרֵהּ לָא תִכְּסוּן בְּיוֹמָא חָד:
@53 וַאֲרֵי תִּכְּסוּן נִכְסַת תּוֹדְתָא קֳדָם יְיָ לְרַעֲוָא לְכוֹן תִּכְּסֻנֵהּ:
@54 בְּיוֹמָא הַהוּא יִתְאֲכֵל לָא תַשְׁאֲרוּן מִנֵהּ עַד צַפְרָא אֲנָא יְיָ:
@55 וְתִטְרוּן פִּקוּדַי וְתַעֲבְּדוּן יָתְהוֹן אֲנָא יְיָ:
@56 וְלָא תְחַלְלוּן יָת שְׁמָא דְקוּדְשַׁי וְאִתְקַדַשׁ בְּגוֹ בְּנֵי יִשְׂרָאֵל אֲנָא יְיָ מְקַדִשְּׁכוֹן:
@57 דְאַפִּיק יָתְכוֹן מֵאַרְעָא דְמִצְרַיִם לְמֶהֱוֵי לְכוֹן לֵאלָהָא אֲנָא יְיָ:
@58 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@59 מַלֵיל עִם בְּנֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן מוֹעֲדַיָא דַיְיָ דִי תְעָרְעוּן יָתְהוֹן מְעָרְעֵי קַדִישׁ אִלֵין אִנוּן מוֹעֲדָי:
@60 שִׁתָּא יוֹמִין תִּתְעֲבֵד עִבִידָא וּבְיוֹמָא שְׁבִיעָאָה שְׁבַת שְׁבָתָא מְעָרַע קַדִישׁ כָּל עִבִידָא לָא תַעֲבְּדוּן שַׁבְּתָא הִיא קֳדָם יְיָ בְּכֹל מוֹתְבָנֵיכוֹן:
@61 אִלֵין מוֹעֲדַיָא דַיְיָ מְעָרְעֵי קַדִישׁ דִי תְעָרְעוּן יָתְהוֹן בְּזִמְנֵיהוֹן:
@62 בְּיַרְחָא קַדְמָאָה בְּאַרְבְּעַת עַשְׂרָא לְיַרְחָא בֵּין שִׁמְשַׁיָא פִּסְחָא קֳדָם יְיָ:
@63 וּבְחַמְשַׁת עַשְׂרָא יוֹמָא לְיַרְחָא הָדֵין חַגָא דְפַטִירַיָא קֳדָם יְיָ שִׁבְעָא יוֹמִין פַּטִיר תֵּיכְלוּן:
@64 בְּיוֹמָא קַדְמָאָה מְעָרַע קַדִישׁ יְהֵי לְכוֹן כָּל עִבִידַת פָּלְחַן לָא תַעֲבְּדוּן:
@65 וּתְקָרְבוּן קֻרְבָּנָא קֳדָם יְיָ שִׁבְעָא יוֹמִין בְּיוֹמָא שְׁבִיעָאָה מְעָרַע קַדִישׁ כָּל עִבִידַת פָּלְחָן לָא תַעֲבְּדוּן:
@66 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@67 מַלֵיל עִם בְּנֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן אֲרֵי תֵעֲלוּן לְאַרְעָא דִי אֲנָא יָהֵב לְכוֹן וְתַחְצְדוּן יָת חֲצָדַהּ וְתַיְתוּן יָת עוּמְרָא רֵישׁ חֲצָדְכוֹן לְוָת כַּהֲנָא:
@68 וִירִים יָת עוּמְרָא קֳדָם יְיָ לְרַעֲוָא לְכוֹן מִבָּתַר יוֹמָא טָבָא יְרִימִנֵהּ כַּהֲנָא:
@69 וְתַעֲבְּדוּן בְּיוֹמָא דַאֲרָמוּתְכוֹן יָת עוּמְרָא אִמַר שְׁלִים בַּר שַׁתֵּהּ לַעֲלָתָא קֳדָם יְיָ:
@70 וּמִנְחָתֵהּ תְּרֵין עֶשְׂרוֹנִין סֻלְתָּא דְפִילָא בִמְשַׁח קֻרְבָּנָא קֳדָם יְיָ לְאִתְקַבָּלָא בְרַעֲוָא וְנִסְכֵּהּ חַמְרָא רַבְעוּת הִינָא:
@71 וּלְחֵם וּקְלִי וּפֵרוּכָן לָא תֵיכְלוּן עַד כְּרַן יוֹמָא הָדֵין עַד אַיְתוֹאֵיכוֹן יָת קֻרְבָּן אֱלָהָכוֹן קְיַם עָלָם לְדָרֵיכוֹן בְּכֹל מוֹתְבָנֵיכוֹן:
@72 וְתִמְנוּן לְכוֹן מִבָּתַר יוֹמָא טָּבָא מִיוֹם אַיְתוֹאֵיכוֹן יָת עוּמְרָא דַאֲרָמוּתָא שִׁבְעָא שָׁבוּעִין שַּׁלְמִין יְהֶוְיָן (נ''א תְּהֶוְיָן):
@73 עַד מִבָּתַר שְׁבוּעֲתָא שְׁבִיעֵתָא תִּמְנוּן חַמְשִׁין יוֹמִין וּתְקַרְבוּן מִנְחָתָא חֲדַתָּא קֳדָם יְיָ:
@74 מִמוֹתְבָנֵיכוֹן תַּיְתוּן לְחֵם אֲרָמוּתָא תַּרְתֵּין (גְרִיצַן) תְּרֵין עֶשְׂרוֹנִין סֻלְתָּא יְהֶוְיָן חֲמִיעַ יִתְאַפְיָן בִּכּוּרִין קֳדָם יְיָ:
@75 וּתְקָרְבוּן עַל לַחְמָא שִׁבְעָא אִמְרִין שַׁלְמִין בְּנֵי שְׁנָא וְתוֹר בַּר תּוֹרֵי חַד וְדִכְרִין תְּרֵין יְהוֹן עֲלָתָא קֳדָם יְיָ וּמִנְחָתְהוֹן וְנִסְכֵּיהוֹן קֻרְבַּן דְמִתְקַבֵּל בְּרַעֲוָא קֳדָם יְיָ:
@76 וְתַעְבְּדוּן צְפִיר בַּר עִזֵי חַד לְחַטָאתָא וּתְרֵין אִמְרִין בְּנֵי שְׁנָא לְנִכְסַת קוּדְשַׁיָא:
@77 וִירִים כַּהֲנָא יָתְהוֹן עַל לְחֵם בִּכּוּרַיָא אֲרָמוּתָא קֳדָם יְיָ עַל תְּרֵין אִמְרִין קוּדְשָׁא יְהוֹן קֳדָם יְיָ לְכַהֲנָא:
@78 וּתְעָרְעוּן בִּכְרַן יוֹמָא הָדֵין מְעָרַע קַדִישׁ יְהֵי לְכוֹן כָּל עִבִידַת פָּלְחָן לָא תַעֲבְּדוּן קְיַם עָלָם בְּכָל מוֹתְבָנֵיכוֹן לְדָרֵיכוֹן:
@79 וּבְמֶחֱצָדְכוֹן יָת חֲצָדָא דְאַרְעֲכוֹן לָא תְשֵׁיצֵי פָּאתָא דְחַקְלָךְ בְּמֶחֱצָדָךְ וּלְקָטָא דַחֲצָדָךְ לָא תְלַקֵט לְעַנְיֵי וּלְגִיוֹרֵי תִּשְׁבּוֹק יָתְהוֹן אֲנָא יְיָ אֱלָהֲכוֹן:
@80 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@81 מַלֵיל עִם בְּנֵי יִשְׂרָאֵל לְמֵימָר בְּיַרְחָא שְׁבִיעָאָה בְּחַד לְיַרְחָא יְהֵי לְכוֹן נְיָחָא דוּכְרָן יַבָּבָא מְעָרַע קַדִישׁ:
@82 כָּל עִבִידַת פָלְחָנָא לָא תַעֲבְּדוּן וּתְקָרְבוּן קֻרְבָּנָא קֳדָם יְיָ:
@83 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@84 בְּרַם בְּעַשְׂרָא לְיַרְחָא שְׁבִיעָאָה הָדֵין יוֹמָא דְכִפּוּרַיָא הוּא מְעָרַע קַדִישׁ יְהֵי לְכוֹן וּתְעַנוּן יָת נַפְשָׁתֵיכוֹן וּתְקָרְבוּן קֻרְבָּנָא קֳדָם יְיָ:
@85 וְכָל עִבִידָא לָא תַעֲבְּדוּן בִּכְרַן יוֹמָא הָדֵין אֲרֵי יוֹמָא דְכִפּוּרַיָא הוּא לְכַפָּרָא עֲלֵיכוֹן קֳדָם יְיָ אֱלָהֲכוֹן:
@86 אֲרֵי כָל אֲנָשָׁא דִי לָא מִתְעַנֵי בִּכְרַן יוֹמָא הָדֵין וְיִשְׁתֵּיצֵי מֵעַמָהָא:
@87 וְכָל אֱנַשׁ דִי תַעְבֵּד כָּל עִבִידָא בִּכְרַן יוֹמָא הָדֵין וְאוֹבֵד יָת אֲנָשָׁא הַהִיא מִגוֹ עַמָהּ:
@88 כָּל עִבִידָא לָא תַעֲבְּדוּן קְיַם עָלָם לְדָרֵיכוֹן בְּכֹל מוֹתְבָנֵיכוֹן:
@89 שְׁבַת שְׁבָתָא הוּא לְכוֹן וּתְעַנוּן יָת נַפְשָׁתֵיכוֹן בְּתִשְׁעָה לְיַרְחָא בְּרַמְשָׁא מֵרַמְשָׁא עַד רַמְשָׁא תְּנוּחוּן נְיַחֲכוֹן:
@90 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@91 מַלֵיל עִם בְּנֵי יִשְׂרָאֵל לְמֵימָר בְּחַמְשָׁא עַשְׂרָא יוֹמָא לְיַרְחָא שְׁבִיעָאָה הָדֵין חַגָא דִמְטַלַיָא שִׁבְעַת יוֹמִין קֳדָם יְיָ:
@92 בְּיּוֹמָא קַדְמָאָה מְעָרַע קַדִישׁ כָּל עִבִידַת פָּלְחָן לָא תַעֲבְּדוּן:
@93 שִׁבְעָא יוֹמִין תְּקָרְבוּן קֻרְבָּנָא קֳדָם יְיָ בְּיוֹמָא תְמִינָאָה מְעָרַע קַדִישׁ יְהֵי לְכוֹן וּתְקָרְבוּן קֻרְבָּנָא קֳדָם יְיָ כְּנֵשׁ תְּהוֹן כָּל עִבִידַת פָּלְחַן לָא תַעֲבְּדוּן:
@94 אִלֵין מוֹעֲדַיָא דַיְיָ דִי תְעָרְעוּן יָתְהוֹן מְעָרְעֵי קַדִישׁ לְקָרָבָא קֻרְבָּנָא קֳדָם יְיָ עֲלָתָא וּמִנְחָתָא נִכְסַת קוּדְשִׁין וְנִסוּכִין פִּתְגַם יוֹם בְּיוֹמֵהּ:
@95 בַּר שַׁבַּיָא דַיְיָ וּבַר מַתְּנָתֵיכוֹן וּבַר כָּל נִדְרֵיכוֹן וּבַר כָּל נִדְבָתֵיכוֹן דִי תִתְּנוּן קֳדָם יְיָ:
@96 בְּרַם בְּחַמְשָׁא עֲשַׂר יוֹמָא לְיַרְחָא שְׁבִיעָאָה בְּמִכְנְשֵׁיכוֹן יָת עֲלַלַת אַרְעָא תְּחַגוּן יָת חַגָא קֳדָם יְיָ שִׁבְעָא יוֹמִין בְּיוֹמָא קַדְמָאָה נְיָחָא וּבְיוֹמָא תְמִינָאָה נְיָחָא:
@97 וְתִסְבוּן לְכוֹן בְּיוֹמָא קַדְמָאָה פֵּרֵי אִילָנָא אֶתְרוֹגִין וְלֻלָבִין וַהֲדַסִין וְעַרְבִין דִנְחָל וְתֶחֱדוּן קֳדָם יְיָ אֱלָהֲכוֹן שַׁבְעַת יוֹמִין:
@98 וּתְחַגוּן יָתֵהּ חַגָא קֳדָם יְיָ שַׁבְעַת יוֹמִין בְּשַׁתָּא קְיַם עָלָם לְדָרֵיכוֹן בְּיַרְחָא שְׁבִיעָאָה תְּחַגוּן יָתֵהּ:
@99 בִּמְטַלַיָא תֵיתְבוּן שַׁבְעַת יוֹמִין כָּל יַצִיבָא בְּיִשְׂרָאֵל יֵתְבוּן בִּמְטַלַיָא:
@100 בְּדִיל דְיִדְעוּן דָרֵיכוֹן אֲרֵי בִמְטַלָיוּת עֲנָנֵי אוֹתֵבִית יָת בְּנֵי יִשְׂרָאֵל בְּאַפָּקוּתִי יָתְהוֹן מֵאַרְעָא דְמִצְרַיִם אֲנָא יְיָ אֱלָהֲכוֹן:
@101 וּמַלִיל מֹשֶׁה יָת סְדַר מוֹעֲדַיָא דַיְיָ וְאַלֵפִנוּן לִבְנֵי יִשְׂרָאֵל:
@102 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@103 פַּקֵד יָת בְּנֵי יִשְׂרָאֵל וְיִסְבוּן לָךְ מְשַׁח זֵיתָא דַכְיָא כָּתִישָׁא לְאַנְהָרָא לְאַדְלָקָא בוֹצִינַיָא תְּדִירָא:
@104 מִבָּרָא לְפָרֻכְתָּא דְסַהֲדוּתָא בְּמַשְׁכַּן זִמְנָא יַסְדַר יָתֵהּ אַהֲרֹן מֵרַמְשָׁא עַד צַפְרָא קֳדָם יְיָ תְּדִירָא קְיָם עָלָם לְדָרֵיכוֹן:
@105 עַל מְנַרְתָּא דָכִיתָא יַסְדַר יָת בּוֹצִינַיָא קֳדָם יְיָ תְּדִירָא:
@106 וְתִסַב סֻלְתָּא וְתֵיפֵי יָתַהּ תַּרְתָּא עַשְׂרֵי גְרִיצָן תְּרֵין עֶשְׂרוֹנִין תְּהֵי גְרִצְתָּא חֲדָא:
@107 וּתְשַׁוִי יָתְהוֹן תַּרְתֵּי סִדְרִין שִׁית סִדְרָא עַל פָּתוֹרָא דַכְיָא קֳדָם יְיָ:
@108 וְתִתֵּן עַל סִדְרָא לְבֹנְתָּא דָכִיתָא וּתְהֵי לִלְחֵם לְאִדְכַּרְתָּא קֻ:רבָּנָא:קָדָם יְיָ:
@109 בְּיוֹמָא דְשַׁבְּתָא בְּיוֹמָא דְשַׁבְּתָא יַסְדְרִנֵהּ קֳדָם יְיָ תְּדִירָא מִן קֳדָם בְּנֵי יִשְׂרָאֵל קְיַם עָלָם:
@110 וּתְהֵי לְאַהֲרֹן וְלִבְנוֹהִי וְיֵכְלֻנֵהּ בַּאֲתַר קַדִישׁ אֲרֵי קֹדֶשׁ קוּדְשִׁין הוּא לֵהּ מִקֻרְבָּנַיָא דַיְיָ קְיַם עָלָם:
@111 וּנְפַק בַּר אִתְּתָא בַת יִשְׂרָאֵל וְהוּא בַּר גְבַר מִצְרָאָה בְּגוֹ בְּנֵי יִשְׂרָאֵל וּנְצוֹ בְּמַשְׁרִיתָא בַּר אִתְּתָא בַת יִשְׂרָאֵל וְגַבְרָא בַּר יִשְׂרָאֵל:
@112 וּפָרֵשׁ בַּר אִתְּתָא בַת יִשְׂרָאֵל יָת שְׁמָא וְאַרְגֵז וְאַיְתִיאוּ יָתֵהּ לְוָת מֹשֶׁה וְשׁוּם אִמֵהּ שְׁלֹמִית בַּת דִבְרִי לְשִׁבְטָא דְדָן:
@113 וְאַסְרוֹהִי בְּבֵית מַטְרָא עַד דְיִתְפָּרַשׁ לְהוֹן עַל גְזֵרַת מֵימְרָא דַיְיָ:
@114 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@115 אַפֵּק יָת דְאַרְגֵז לְמִבָּרָא לְמַשְּׁרִיתָא וְיִסְמְכוּן כָּל דִי שְׁמָעוּ יָת יְדֵיהוֹן עַל רֵישֵׁהּ וְיִרְגְמוּן יָתֵהּ כָּל כְּנִשְּׁתָּא:
@116 וְעִם בְּנֵי יִשְׂרָאֵל תְּמַלֵל לְמֵימָר גְבַר גְבַר דִי יַרְגֵז קֳדָם אֱלָהֵהּ וִיקַבֵּל חוֹבֵהּ:
@117 וְדִי פָרֵשׁ שְׁמָא דַיְיָ אִתְקְטָּלָא יִתְקְטֵל מִרְגַם יִרְגְמוּן בֵּהּ כָּל כְּנִשְׁתָּא כְּגִיוֹרָא כְּיַצִיבָא בְּפָרָשׁוּתֵהּ שְׁמָא יִתְקְטֵל:
@118 וּגְבַר אֲרֵי יִקְטוֹל כָּל נַפְשָׁא דַאֲנָשָׁא אִתְקְטָלָא יִתְקְטֵל:
@119 וּדְיִקְטוֹל נְפַשׁ בְּעִירָא יְשַׁלְמִנַהּ נַפְשָׁא חֳלַף נַפְשָׁא:
@120 וּגְבַר אֲרֵי יִתֵּן מוּמָא בְּחַבְרֵהּ כְּמָא דִי עֲבַד כֵּן יִתְעֲבֵד לֵיהּ:
@121 תַּבְרָא חֳלַף תַּבְרָא עֵינָא חֳלַף עֵינָא שִׁנָא חֳלַף שִׁנָא כְּמָא דִי יִתֵּן מוּמָא בַּאֲנָשָׁא כֵּן יִתְיְהֵב בֵּהּ:
@122 וּדְיִקְטוֹל בְּעִירָא יְשַׁלְמִנַהּ וּדְיִקְטוֹל אֲנָשָׁא יִתְקְטֵל:
@123 דִינָא חֲדָא יְהֵי לְכוֹן כְּגִיוֹרָא כְּיַצִיבָא יְהֵי אֲרֵי אֲנָא יְיָ אֱלָהֲכוֹן:
@124 וּמַלִיל מֹשֶׁה עִם בְּנֵי יִשְׂרָאֵל וְאַפִּיקוּ יָת דְאַרְגֵז לְמִבָּרָא לְמַשְׁרִיתָא וּרְגָמוּ יָתֵהּ אַבְנָא וּבְנֵי יִשְׂרָאֵל עֲבָדוּ כְּמָא דִי פַּקֵיד יְיָ יָת מֹשֶׁה: פפפ:

@1 **אמר אל הכהנים.** אמר ואמרת, להזהיר גדולים על הקטנים: **בני אהרן.** יכול חללים, תלמוד לומר הכהנים: **בני אהרן.** אף בעלי מומין במשמע: **בני אהרן.** ולא בנות אהרן: **לא יטמא בעמיו.** בעוד שהמת בתוך עמיו, יצא מת מצוה:
@2 **כי אם לשארו.** אין שארו אלא אשתו:
@3 **הקרובה.** לרבות את הארוסה: **אשר לא היתה לאיש.** למשכב: **לה יטמא.** מצוה:
@4 **לא יטמא בעל בעמיו להחלו.** לא יטמא לאשתו פסולה שהוא מחלל בה בעודה עמו. וכן פשוטו של מקרא לא יטמא בעל בשארו בעוד שהוא בתוך עמיו, שיש לה קוברין, שאינה מת מצוה, ובאיזה שאר אמרתי, באותו שהוא להחלו, להתחלל הוא מכהנתו:
@5 **לא יקרחו קרחה.** על מת. והלא אף ישראל הזהרו על כך, אלא לפי שנאמר בישראל (דברים יד א) בין עיניכם, יכול לא יהא חיב על כל הראש, תלמוד לומר בראשם, וילמדו ישראל מהכהנים בגזרה שוה, נאמר כאן קרחה ונאמר להלן בישראל קרחה, מה כאן כל הראש אף להלן כל הראש במשמע, כל מקום שיקרח בראש. ומה להלן על מת, אף כאן על מת: **ופאת זקנם לא יגלחו.** לפי שנאמר בישראל (ויקרא יט כז) ולא תשחית, יכול לקטו במלקט וברהיטני יהא חיב, לכך נאמר לא יגלחו, שאינו חיב אלא על דבר הקרוי גלוח ויש בו השחתה, וזהו תער: **ובבשרם לא ישרטו שרטת.** לפי שנאמר בישראל (ויקרא שם כח) ושרט לנפש לא תתנו, יכול שרט חמש שריטות לא יהא חיב אלא אחת, תלמוד לומר לא ישרטו שרטת, לחייב על כל שריטה ושריטה. שתיבה זו יתרה היא לדרוש, שהיה לו לכתוב לא ישרטו ואני יודע שהיא שרטת:
@6 **קדשים יהיו.** על כרחם יקדישום בית דין בכך:
@7 **זנה.** שנבעלה בעילת ישראל האסור לה, כגון חיבי כרתות או נתין או ממזר: **חללה.** שנלדה מן הפסולים שבכהנה, כגון בת אלמנה מכהן גדול או בת גרושה וחלוצה מכהן הדיוט, וכן שנתחללה מן הכהנה על ידי ביאת אחד מן הפסולים לכהנה:
@8 **וקדשתו.** על כרחו, שאם לא רצה לגרש, הלקהו ויסרהו עד שיגרש: **קדש יהיה לך.** נהוג בו קדשה לפתוח ראשון בכל דבר ולברך ראשון בסעודה:
@9 **כי תחל לזנות.** כשתתחלל על ידי זנות, שהיתה בה זיקת בעל וזנתה או מן האירוסין או מן הנשואין. ורבותינו נחלקו בדבר, והכל מודים שלא דבר הכתוב בפנויה: **את אביה היא מחללת.** חללה ובזתה את כבודו, שאומרים עליו ארור שזו ילד, ארור שזו גדל:
@10 **לא יפרע.** לא יגדל פרע על אבל. ואיזהו גדול פרע, יותר משלשים יום:
@11 **ועל כל נפשת מת** וגו' **.** באהל המת: **נפשת מת.** להביא רביעית דם מן המת שמטמא באהל: **לאביו ולאמו לא יטמא.** לא בא אלא להתיר לו מת מצוה:
@12 **ומן המקדש לא יצא.** אינו הולך אחר המטה. ועוד מכאן למדו רבותינו שכהן גדול מקריב אונן, וכן משמעו, אף אם מתו אביו ואמו אינו צריך לצאת מן המקדש אלא עובד עבודה: **ולא יחלל את מקדש.** שאינו מחלל בכך את העבודה שהתיר לו הכתוב, הא כהן הדיוט שעבד אונן חלל:
@14 **וחללה.** שנלדה מפסולי כהנה:
@15 **ולא יחלל זרעו.** הא אם נשא אחת מן הפסולות, זרעו המנה חלל מדין קדשת כהנה:
@17 **לחם אלהיו.** מאכל אלהיו, כל סעודה קרויה לחם, כמו (דניאל ה א) עבד לחם רב:
@18 **כי כל איש אשר בו מום לא יקרב.** אינו דין שיקרב, כמו (מלאכי א ח) הקריבהו נא לפחתך: **חרם.** שחטמו שקוע בין שתי העינים, שכוחל שתי עיניו כאחת: **או שרוע.** שאחד מאיבריו גדול מחברו, עינו אחת גדולה ועינו אחת קטנה, או שוקו אחת ארכה מחברתה:
@20 **או גבן.** שורצילו''ש בלע''ז [בעל גבות ארוכות] שגביני עיניו שערן ארוך ושוכב: **או דק.** שיש לו בעיניו דוק שקורין טיל''א [קרום] , כמו (ישעיה מ כב) הנוטה כדוק: **או תבלל.** דבר המבלבל את העין, כגון חוט לבן הנמשך מן הלבן ופוסק בסירא, שהוא עוגל המקיף את השחור, שקוראים פרוניל''א [אישון] , והחוט הזה פוסק את העוגל ונכנס בשחור. ותרגום תבלל חליז, לשון חלזון, שהוא דומה לתולעת אותו החוט. וכן כנוהו חכמי ישראל במומי הבכור חלזון נחש עינב (בכורות לח א) : **גרב וילפת.** מיני שחין הם: גרב, זו החרס. שחין היבש מבפנים ומבחוץ: ילפת, היא חזזית המצרית. ולמה נקראת ילפת שמלפפת והולכת עד יום המיתה, והוא לח מבחוץ ויבש מבפנים. ובמקום אחר קורא לגרב שחין, הלח מבחוץ ויבש מבפנים, שנאמר (דברים כח כז) ובגרב ובחרס, כשסמוך גרב אצל חרס קורא לילפת גרב, וכשהוא סמוך אצל ילפת קורא לחרס גרב, כך מפורש בבכורות (מא א) : **מרוח אשך.** לפי התרגום מריס פחדין, שפחדיו מרססים, שביצים שלו כתותין. פחדין כמו (איוב מ יז) גידי פחדו ישורגו:
@21 **כל איש אשר בו מום.** לרבות שאר מומין: **מום בו.** בעוד מומו בו פסול, הא אם עבר מומו כשר: **לחם אלהיו.** כל מאכל קרוי לחם:
@22 **מקדשי הקדשים.** אלו קדשי הקדשים: **ומן הקדשים יאכל.** אלו קדשים קלים. ואם נאמרו קדשי הקדשים למה נאמרו קדשים קלים, אם לא נאמרו הייתי אומר בקדשי הקדשים יאכל בעל מום, שמצינו שהתרו לזר, שאכל משה בשר המלואים, אבל בחזה ושוק של קדשים קלים לא יאכל, שלא מצינו זר חולק בהן, לכך נאמרו קדשים קלים. כך מפורש בזבחים (קא:) :
@23 **אך אל הפרכת.** להזות שבע הזאות שעל הפרכת: **ואל המזבח.** החיצון. ושניהם הצרכו להכתב, ומפורש בתורת כהנים: **ולא יחלל את מקדשי.** שאם עבד, עבודתו מחללת להפסל:
@24 **וידבר משה.** המצוה הזאת: **אל אהרן ואל בניו ואל כל בני ישראל.** להזהיר בית דין על הכהנים:
@26 **וינזרו.** אין נזירה אלא פרישה, וכן הוא אומר (יחזקאל יד ז) וינזר מאחרי, (ישעיה א ד) נזורו אחור, יפרשו מן הקדשים בימי טמאתן. דבר אחר: וינזרו מקדשי בני ישראל אשר הם מקדישים לי ולא יחללו את שם קדשי. סרס המקרא ודרשהו, אשר הם מקדשים לי ולא יחללו את שם קדשי: **אשר הם מקדשים לי.** לרבות קדשי כהנים עצמן:
@27 **כל איש אשר יקרב.** אין קריבה זו אלא אכילה, וכן מצינו שנאמרה אזהרת אכילת קדשים בטמאה בלשון נגיעה בכל קדש לא תגע (ויקרא יב ד) , אזהרה לאוכל. ולמדוה רבותינו מגזרה שוה. ואי אפשר לומר שחיב על הנגיעה, שהרי נאמר כרת על האכילה בצו את אהרן (ויקרא ז כ. כא) שתי כריתות זו אצל זו, ואם על הנגיעה חיב לא הצרך לחיבו על האכילה, וכן נדרש בתורת כהנים וכי יש נוגע חיב, אם כן מה תלמוד לומר יקרב, משיכשר לקרב, שאין חיבין עליו משום טמאה, אלא אם כן קרבו מתיריו. ואם תאמר שלש כריתות בטמאת כהנים למה, כבר נדרשו במסכת שבועות אחת לכלל ואחת לפרט וכו' (שבועות ז א) : **וטמאתו עליו.** וטמאת האדם עליו, יכול בבשר הכתוב מדבר, וטמאתו של בשר עליו, ובטהור שאכל את הטמא הכתוב מדבר, הרי כבר נאמר (ויק' ז יט) והבשר אשר יגע בכל טמא לא יאכל, אלא על כרחך ממשמעו אתה למד, במי שטמאתו פורחת ממנו הכתוב מדבר, וזהו האדם שיש לו טהרה בטבילה: **ונכרתה** וגו' **.** יכול מצד זה לצד זה, יכרת ממקומו ויתישב במקום אחר, תלמוד לומר אני ה', בכל מקום אני:
@28 **מזרע אהרן.** אין לי אלא זרעו, גופו מנין, תלמוד לומר והוא צרוע, שיכול הואיל ומקריב אונן יקריב צרוע וזב, תלמוד לומר והוא: **עד אשר יטהר.** ביאת השמש, או אינו אלא טבילה, נאמר כאן וטהר, ונאמר למטה וטהר (פסוק ז) ובא השמש וטהר, מה להלן ביאת שמש, אף כאן ביאת שמש: **בכל טמא נפש.** במי שנטמא במת:
@29 **בכל שרץ אשר יטמא לו.** בשעור הראוי לטמא, בכעדשה: **או באדם.** במת: **אשר יטמא לו.** כשיעורו לטמא, וזהו כזית: **לכל טמאתו.** לרבות נוגע בזב וזבה, נדה ויולדת ובמצורע:
@30 **נפש אשר תגע בו.** באחד מן הטמאים הללו:
@31 **ואחר יאכל מן הקדשים.** נדרש ביבמות בתרומה, שמתר לאכלה בהערב השמש: **מן הקדשים.** ולא כל הקדשים:
@32 **נבלה וטרפה לא יאכל לטמאה בה.** לענין הטמאה הזהיר כאן, שאם אכל נבלת עוף טהור, שאין לה טמאת מגע ומשא אלא טמאת אכילה בבית הבליעה, אסור לאכול בקדשים. וצריך לומר וטרפה, מי שיש במינו טרפה, יצא נבלת עוף טמא שאין במינו טרפה:
@33 **ושמרו את משמרתי.** מלאכול תרומה בטמאת הגוף: **ומתו בו.** למדנו שהיא מיתה בידי שמים:
@34 **לא יאכל קדש.** בתרומה הכתוב מדבר, שכל הענין דבר בה: **תושב כהן ושכיר.** תושבו של כהן ושכירו, לפיכך תושב זה נקוד פתח, לפי שהוא דבוק. ואיזהו תושב, זה נרצע שהוא קנוי לו עד היובל, ואיזהו שכיר, זה קנוי קנין שנים, שיוצא בשש, בא הכתוב ולמדך כאן שאין גופו קנוי לאדוניו לאכול בתרומתו:
@35 **וכהן כי יקנה נפש.** עבד כנעני שקנוי לגופו: **ויליד ביתו.** אלו בני השפחות. ואשת כהן אוכלת בתרומה מן המקרא הזה, שאף היא קנין כספו. ועוד למד ממקרא אחר (במדבר יח יא) כל טהור בביתך וגו' בספרי:
@36 **לאיש זר.** ללוי ולישראל:
@37 **אלמנה וגרושה.** מן האיש הזר: **וזרע אין לה.** ממנו: **ושבה.** הא אם יש לה זרע ממנו אסורה בתרומה כל זמן שהזרע קים: **וכל זר לא יאכל בו.** לא בא אלא להוציא את האונן שמתר בתרומה. זרות אמרתי לך, ולא אנינות:
@38 **כי יאכל קדש.** תרומה: **ונתן לכהן את הקדש.** דבר הראוי להיות קדש, שאינו פורע לו מעות אלא פירות של חלין, והן נעשין תרומה:
@39 **ולא יחללו** וגו' **.** להאכילם לזרים:
@40 **והשיאו אותם.** את עצמם יטענו עון באכלם את קדשיהם, שהבדלו לשם תרומה וקדשו ונאסרו עליהם. ואנקלוס שתרגם במיכלהון בסואבא, שלא לצורך תרגמו כן: **והשיאו אותם.** זה אחד משלשה אתים שהיה רבי ישמעאל דורש בתורה שמדברים באדם עצמו, וכן (במ' ו יג) ביום מלאת ימי נזרו יביא אתו, הוא יביא את עצמו. וכן (דברים לד ו) ויקבור אתו בגיא, הוא קבר את עצמו, כך נדרש בספרי:
@42 **נדריהם.** הרי עלי: **נדבתם.** הרי זו:
@43 **לרצנכם.** הביאו דבר הראוי לרצות אתכם לפני, שיהא לכם לרצון אפיימני''ט בלע''ז . ואיזהו הראוי לרצון, **תמים זכר בבקר בכשבים ובעזים.** אבל בעולת העוף אין צריך תמות וזכרות, ואינו נפסל במום אלא בחסרון אבר:
@45 **לפלא נדר.** להפריש בדבורו:
@46 **עורת.** שם דבר של מום עורון בלשון נקבה, שלא יהא בו מום של עורת: **או שבור.** לא יהיה: **חרוץ.** ריס של עין שנסדק או שנפגם, וכן שפתו שנסדקה או נפגמה: **יבלת.** ורוא''ה בלע''ז : **גרב.** מין חזזית וכן ילפת. ולשון ילפת, כמו (שופטים טז כט) וילפת שמשון, שאחוזה בו עד יום מיתה, שאין לה רפואה: **לא תקריבו.** שלש פעמים, להזהיר על הקדשן ועל שחיטתן ועל זריקת דמן: **ואשה לא תתנו.** אזהרת הקטרתן:
@47 **שרוע.** אבר גדול מחברו: **וקלוט.** פרסותיו קלוטות: **נדבה תעשה אתו.** לבדק הבית: **ולנדר.** למזבח: **לא ירצה.** איזהו הקדש בא לרצות, הוי אומר זה הקדש המזבח:
@48 **ומעוך וכתות ונתוק וכרות.** בביצים או בגיד: **מעוך.** ביציו מעוכין ביד: **כתות.** כתושים יותר ממעוך: **נתוק.** תלושין ביד עד שנפסקו חוטים שתלויים בהן, אבל נתונים הם בתוך הכיס, והכיס לא נתלש: **וכרות.** כרותין בכלי ועודן בכיס: **ומעוך.** תרגומו ודמריס, זה לשונו בארמית, לשון כתישה: **וכתות.** תרגומו ודרסיס, כמו (עמוס ו יא) הבית הגדול רסיסים, בקיעות דקות, וכן (שבת פ ב) קנה המרסס: **ובארצכם לא תעשו.** דבר זה, לסרס שום בהמה וחיה ואפלו טמאה, לכך נאמר בארצכם, לרבות כל אשר בארצכם, שאי אפשר לומר לא נצטוו על הסרוס אלא בארץ, שהרי סרוס חובת הגוף הוא, וכל חובת הגוף נוהגת בין בארץ בין בחוצה לארץ:
@49 **ומיד בן נכר.** נכרי שהביא קרבן ביד כהן להקריבו לשמים לא תקריבו לו בעל מום. ואף על פי שלא נאסרו בעלי מומין לקרבן בני נח אלא אם כן מחסרי אבר, זאת נוהגת בבמה שבשדות, אבל על המזבח שבמשכן לא תקריבוה, אבל תמימה תקבלו מהם, לכך נאמר למעלה איש איש (לעיל פסוק יח) , לרבות את הנכרים שנודרים נדרים ונדבות כישראל: **משחתם.** חבולהון: **לא ירצו לכם.** לכפר עליכם:
@51 **כי יולד.** פרט ליוצא דופן:
@52 **אתו ואת בנו.** נוהג בנקבה, שאסור לשחוט האם והבן או הבת, ואינו נוהג בזכרים, ומתר לשחוט האב והבן או האב והבת: **אתו ואת בנו.** אף בנו ואותו במשמע:
@53 **לרצנכם תזבחו.** תחלת זביחתכם הזהרו שתהא לרצון לכם. ומהו הרצון, ביום ההוא יאכל. לא בא להזהיר אלא שתהא שחיטה על מנת כן, אל תשחטוהו על מנת לאכלו למחר, שאם תחשבו בו מחשבת פסול לא יהא לכם לרצון. דבר אחר לרצונכם, לדעתכם, מכאן למתעסק שפסול בשחיטת קדשים. ואף על פי שפרט בנאכלים לשני ימים, חזר ופרט בנאכלין ליום אחד שתהא זביחתן על מנת לאכלן בזמנן:
@54 **ביום ההוא יאכל.** לא בא להזהיר אלא שתהא שחיטה על מנת כן, שאם לקבוע לו זמן אכילה, כבר כתוב (ויקרא ז טו) ובשר זבח תודת שלמיו וגו' : **אני ה'.** דע מי גזר על הדבר ואל יקל בעיניך:
@55 **ושמרתם.** זו המשנה: **ועשיתם.** זה המעשה:
@56 **ולא תחללו.** לעבור על דברי מזידין. ממשמע שנאמר ולא תחללו, מה תלמוד לומר ונקדשתי, מסור עצמך וקדש שמי. יכול ביחיד, תלמוד לומר בתוך בני ישראל, וכשהוא מוסר עצמו, ימסור עצמו על מנת למות, שכל המוסר עצמו על מנת הנס, אין עושין לו נס, שכן מצינו בחנניה מישאל ועזריה שלא מסרו עצמן על מנת הנס, שנאמר (דניאל ג יח) והן לא, ידיע להוא לך מלכא די לאלהך לא איתנא פלחין וגו' , מציל ולא מציל, ידיע להוא לך וגו' :
@57 **המוציא אתכם.** על מנת כן: **אני ה'.** נאמן לשלם שכר:
@59 **דבר אל בני ישראל** וגו' **מועדי ה'.** עשה מועדות שיהיו ישראל מלמדין בהם, שמעברים את השנה על גליות שנעקרו ממקומם לעלות לרגל ועדין לא הגיעו לירושלים:
@60 **ששת ימים.** מה ענין שבת אצל מועדות, ללמדך שכל המחלל את המועדות מעלין עליו כאלו חלל את השבתות. וכל המקים את המועדות, מעלין עליו כאלו קים את השבתות:
@61 **אלה מועדי ה'.** למעלה מדבר בעבור שנה, וכאן מדבר בקדוש החדש:
@62 **בין הערבים.** משש שעות ולמעלה: **פסח לה'.** הקרבת קרבן ששמו פסח:
@65 **והקרבתם אשה** וגו' **.** הם המוספין האמורים בפרשת פנחס ולמה נאמרו כאן, לומר לך שאין המוספין מעכבין זה את זה: **והקרבתם אשה לה'.** מכל מקום, אם אין פרים הבא אילים, ואם אין פרים ואילים, הבא כבשים: **שבעת ימים.** כל מקום שנאמר שבעת שם דבר הוא, שבוע של ימים, שטיינ''א בלע''ז [קבוצה של שבעה ימים רצופים] , וכן כל לשון שמונת, ששת, חמשת, שלשת: **מלאכת עבדה.** אפלו מלאכות החשובות לכם עבודה וצורך, שיש חסרון כיס בבטלה שלהן, כגון דבר האבד. כך הבנתי מתורת כהנים, דקתני יכול אף חלו של מועד יהא אסור במלאכת עבודה וכו' :
@67 **ראשית קצירכם.** שתהא ראשונה לקציר: **עמר.** עשירית האיפה, כך היתה שמה, כמו (שמות טז יח) וימדו בעמר:
@68 **והניף.** כל תנופה מוליך ומביא, מעלה ומוריד. מוליך ומביא לעצור רוחות רעות, מעלה ומוריד לעצור טללים רעים: **לרצנכם.** אם תקריבו כמשפט זה, יהיו לרצון לכם: **ממחרת השבת.** ממחרת יום טוב הראשון של פסח, שאם אתה אומר שבת בראשית, אי אתה יודע איזהו:
@69 **ועשיתם:. כבש.** חובה לעמר הוא בא:
@70 **ומנחתו.** מנחת נסכיו: **שני עשרנים.** כפולה היתה: **ונסכה יין רביעית ההין.** אף על פי שמנחתו כפולה, אין נסכיו כפולים:
@71 **וקלי.** קמח עשוי מכרמל רך שמיבשין אותו בתנור: **וכרמל.** הן קליות שקורין גרניד''ש [שבלים] : **בכל משבתיכם.** נחלקו בו חכמי ישראל, יש שלמדו מכאן שהחדש נוהג בחוצה לארץ, ויש אומרים לא בא אלא ללמד שלא נצטוו על החדש אלא לאחר ירשה וישיבה, משכבשו וחלקו:
@72 **ממחרת השבת.** ממחרת יום טוב: **תמימת תהיינה.** מלמד שמתחיל ומונה מבערב, שאם לא כן אינן תמימות:
@73 **השבת השביעת.** כתרגומו שבועתא שביעתא: **עד ממחרת השבת השביעת תספרו.** ולא עד בכלל, והן ארבעים ותשעה יום: **חמשים יום והקרבתם מנחה חדשה לה'.** ביום החמשים תקריבוה. ואומר אני זהו מדרשו, אבל פשוטו עד ממחרת השבת השביעית, שהוא יום חמשים, תספרו. ומקרא מסורס הוא: **מנחה חדשה.** היא המנחה הראשונה שהובאה מן החדש. ואם תאמר, הרי קרבה מנחת העומר, אינה כשאר כל המנחות, שהיא באה מן השעורים:
@74 **ממושבתיכם.** ולא מחוצה לארץ: **לחם תנופה.** לחם תרומה המורם לשם גבוה, וזו היא המנחה החדשה האמורה למעלה: **בכורים.** ראשונה לכל המנחות, אף למנחת קנאות הבאה מן השעורים, לא תקרב מן החדש קודם לשתי הלחם:
@75 **על הלחם.** בגלל הלחם, חובה ללחם: **ומנחתם ונסכיהם.** כמשפט מנחה ונסכים המפורשים בכל בהמה בפרשת נסכים (במדבר טו ד. י) שלשה עשרונים לפר ושני עשרונים לאיל ועשרון לכבש, זו היא המנחה. והנסכים חצי ההין לפר ושלישית ההין לאיל ורביעית ההין לכבש:
@76 **ועשיתם שעיר עזים.** יכול שבעת הכבשים והשעיר האמורים כאן הם שבעת הכבשים והשעיר האמורים בחומש הפקודים, כשאתה מגיע אצל פרים ואילים אינן הם, אמור מעתה אלו לעצמן ואלו לעצמן, אלו קרבו בגלל הלחם ואלו למוספין:
@77 **והניף הכהן אתם תנופה.** מלמד שטעונין תנופה מחיים, יכול כלם, תלמוד לומר על שני כבשים: **קדש יהיו.** לפי ששלמי יחיד קדשים קלים, הזקק לומר בשלמי צבור שהם קדשי קדשים:
@79 **ובקצרכם.** חזר ושנה לעבור עליהם בשני לאוין. אמר רבי אבדימי ברבי יוסף מה ראה הכתוב לתנה באמצע הרגלים, פסח ועצרת מכאן וראש השנה ויום הכפורים והחג מכאן, ללמדך שכל הנותן לקט שכחה ופאה לעני כראוי, מעלין עליו כאלו בנה בית המקדש והקריב קרבנותיו בתוכו: **תעזב.** הנח לפניהם והם ילקטו, ואין לך לסיע לאחד מהם: **אני ה' אלהיכם.** נאמן לשלם שכר:
@81 **זכרון תרועה.** זכרון פסוקי זכרונות ופסוקי שופרות, לזכור לכם עקידת יצחק שקרב תחתיו איל:
@82 **והקרבתם אשה.** המוספים האמורים בחומש הפקודים:
@84 **אך.** כל אכין ורקין שבתורה מיעוטין, מכפר הוא לשבים ואינו מכפר על שאינם שבים:
@87 **והאבדתי.** לפי שהוא אומר כרת בכל מקום ואיני יודע מה הוא, כשהוא אומר והאבדתי, למד על הכרת שאינו אלא אבדן:
@88 **כל מלאכה** וגו' **.** לעבור עליו בלאוין הרבה, או להזהיר על מלאכת לילה כמלאכת יום:
@92 **מקרא קדש.** קדשהו בכסות נקיה ובתפלה, ובשאר ימים טובים במאכל ובמשתה ובכסות נקיה ובתפלה:
@93 **עצרת הוא.** עצרתי אתכם אצלי כמלך שזמן את בניו לסעודה לכך וכך ימים, כיון שהגיע זמנן להפטר אמר בני בבקשה מכם, עכבו עמי עוד יום אחד, קשה עלי פרידתכם: **כל מלאכת עבדה.** אפלו מלאכה שהיא עבודה לכם, שאם לא תעשוה יש חסרון כיס בדבר: **לא תעשו.** יכול אף חלו של מועד יהא אסור במלאכת עבודה, תלמוד לומר היא:
@94 **עלה ומנחה.** מנחת נסכים הקרבה עם העולה: **דבר יום ביומו.** חק הקצוב בחומש הפקודים: **דבר יום ביומו.** הא אם עבר יומו בטל קרבנו:
@96 **אך בחמשה עשר יום:. תחגו.** קרבן שלמים לחגיגה. יכול תדחה את השבת, תלמוד לומר אך, הואיל ויש לה תשלומין כל שבעה: **באספכם את תבואת הארץ.** שיהא חדש שביעי זה בא בזמן אסיפה, מכאן שנצטוו לעבר את השנים, שאם אין העבור, פעמים שהוא בא באמצע הקיץ או החורף: **תחגו.** שלמי חגיגה: **שבעת ימים.** אם לא הביא בזה יביא בזה. יכול יהא מביאן כל שבעה, תלמוד לומר וחגתם אתו, יום אחד במשמע, ולא יותר. ולמה נאמר שבעה, לתשלומין:
@97 **פרי עץ הדר.** עץ שטעם עצו ופריו שוה: **הדר.** הדר באילנו משנה לשנה, וזהו אתרוג: **כפת תמרים.** חסר וי''ו, למד שאינה אלא אחת: **וענף עץ עבת.** שענפיו קלועים כעבותות וכחבלים, וזהו הדס העשוי כמין קליעה:
@99 **האזרח.** זה אזרח: **בישראל.** לרבות את הגרים:
@100 **כי בסכות הושבתי.** ענני כבוד:
@103 **צו את בני ישראל.** זו פרשת מצות הנרות. ופרשת ואתה תצוה לא נאמרה אלא על סדר מלאכת המשכן לפרש צורך המנורה. וכן משמע, ואתה סופך לצוות את בני ישראל על כך: **שמן זית זך.** שלשה שמנים יוצאים מן הזית, הראשון קרוי זך, והן מפורשים במנחות (פט א) ובתורת כהנים: **תמיד.** מלילה ללילה, כמו עולת תמיד שאינה אלא מיום ליום:
@104 **לפרכת העדת.** שלפני הארון, שהוא קרוי עדות. ורבותינו דרשו על נר מערבי, שהוא עדות לכל באי עולם שהשכינה שורה בישראל, שנותן בה שמן כמדת חברותיה וממנה היה מתחיל ובה היה מסים: **יערך אתו אהרן מערב עד בקר.** יערוך אותו עריכה הראויה למדת כל הלילה, ושערו חכמים חצי לוג לכל נר ונר, והן כדאי אף ללילי תקופת טבת, ומדה זו הקבעה להם:
@105 **המנרה הטהרה.** שהיא זהב טהור. דבר אחר על טהרה של מנורה, שמטהרה ומדשנה תחלה מן האפר:
@107 **שש המערכת.** שש חלות המערכה האחת: **השלחן הטהר.** של זהב טהור. דבר אחר על טהרו של שלחן, שלא יהיו הסניפין מגביהין את הלחם מעל גבי השלחן:
@108 **ונתת על המערכת.** על כל אחת משתי המערכות היו שני בזכי לבונה, מלא קומץ לכל אחת: **והיתה.** הלבונה הזאת: **ללחם לאזכרה.** שאין מן הלחם לגבוה כלום, אלא הלבונה נקטרת כשמסלקין אותו בכל שבת ושבת. והיא לזכרון ללחם, שעל ידה הוא נזכר למעלה, כקומץ שהוא אזכרה למנחה:
@110 **והיתה.** המנחה הזאת, שכל דבר הבא מן התבואה בכלל מנחה הוא: **ואכלהו.** מוסב על הלחם, שהוא לשון זכר:
@111 **ויצא בן אשה ישראלית.** מהיכן יצא, רבי לוי אומר מעולמו יצא. רבי ברכיה אומר מפרשה שלמעלה יצא. לגלג ואמר ביום השבת יערכנו, דרך המלך לאכול פת חמה בכל יום, או שמא פת צוננת של תשעה ימים, בתמיהה. ומתניתא אמרה מבית דינו של משה יצא מחיב. בא לטע אהלו בתוך מחנה דן, אמרו לו מה טיבך לכאן, אמר להם מבני דן אני. אמרו לו (במדבר ב) איש על דגלו באתת לבית אבותם כתיב. נכנס לבית דינו של משה ויצא מחיב, עמד וגדף: **בן איש מצרי.** הוא המצרי שהרגו משה: **בתוך בני ישראל.** מלמד שנתגיר: **וינצו במחנה.** על עסקי המחנה: **ואיש הישראלי.** זה שכנגדו, שמחה בו מטע אהלו:
@112 **ויקב.** כתרגומו ופרש, שנקב שם המיוחד וגדף, והוא שם המפורש ששמע מסיני: **ושם אמו שלמית בת דברי.** שבחן של ישראל שפרסמה הכתוב לזו, לומר, שהיא לבדה היתה זונה: **שלמית.** דהות פטפטה שלם עלך, שלם עלך, שלם עליכון, מפטפטת בדברים שואלת בשלום הכל: **בת דברי.** דברנית היתה מדברת עם כל אדם, לפיכך קלקלה: **למטה דן.** מגיד שהרשע גורם גנאי לו גנאי לאביו גנאי לשבטו, כיוצא בו (שמות לא ו) אהליאב בן אחיסמך למטה דן, שבח לו שבח לאביו שבח לשבטו:
@113 **ויניחהו.** לבדו, ולא הניחו מקושש עמו, ששניהם היו בפרק אחד. ויודעים היו שהמקושש במיתה, שנאמר (שמות לא יד) מחלליה מות יומת אבל לא פרש להם באיזו מיתה, לכך נאמר (במדבר טו לד) כי לא פרש מה יעשה לו. אבל במקלל הוא אומר לפרוש להם, שלא היו יודעים אם חיב מיתה אם לאו:
@115 **השמעים.** אלו העדים: **כל.** להביא את הדינים: **את ידיהם.** אומרים לו דמך בראשך ואין אנו נענשים במיתתך שאתה גרמת לך: **כל העדה.** במעמד כל העדה. מכאן ששלוחו שלאדם כמותו:
@116 **ונשא חטאו.** בכרת, כשאין התראה:
@117 **ונקב שם.** אינו חיב עד שיפרש את השם, ולא המקלל בכנוי: **ונקב.** לשון קללה, כמו (במדבר כג ח) מה אקב:
@118 **ואיש כי יכה.** לפי שנאמר (שמות כא יב) מכה איש ומת, אין לי אלא שהרג את האיש, אשה וקטן מנין, תלמוד לומר כל נפש אדם:
@121 **כן ינתן בו.** פרשו רבותינו, שאינו נתינת מום ממש אלא תשלומי ממון, שמין אותו כעבד, לכך כתוב בו לשון נתינה, דבר הנתון מיד ליד:
@122 **ומכה בהמה ישלמנה.** למעלה דבר בהורג בהמה, וכאן דבר בעושה בה חבורה: **ומכה אדם יומת.** אפלו לא הרגו אלא עשה בו חבורה, שלא נאמר כאן נפש ובמכה אביו ואמו דבר הכתוב, ובא להקישו למכה בהמה מה מכה בהמה מחיים, אף מכה אביו ואמו מחיים, פרט למכה לאחר מיתה, לפי שמצינו שהמקללו לאחר מיתה חיב, הצרך לומר במכה שפטור. ומה בבהמה בחבלה, שאם אין חבלה אין תשלומין, אף מכה אביו ואמו אינו חיב עד שיעשה בהם חבורה:
@123 **אני ה' אלהיכם.** אלהי כלכם, כשם שאני מיחד שמי עליכם כך אני מיחד שמי על הגרים:
@124 **ובני ישראל עשו.** כל המצוה האמורה בסקילה במקום אחר דחיה, רגימה ותליה:

@1 **ויאמר ה' וגו'**. צריך לדעת למה שינה מסדר הרגיל לומר בכל התורה דבר אל וגו'. עוד למה הקדים התואר למתואר שהיה צריך לומר בני אהרן הכהנים. ודרשות שדרשו חז''ל (תו''כ) במקומן עומדים הגם שידבר בסדר זה. ויתבאר על דרך מה שאמרו ז''ל (תנחומא כאן) וזה לשונם אמר הקב''ה למשה אין נאה ליוצא ונכנס לפני להסתכל במת וכו' ע''כ, והוא אומרו **אמור** לשון מעלה, אל הכהנים פירוש לצד שהם כהנים משרתי פני מלך, ומה היא המעלה שלא יטמאו לנפש אדם כמאמרם ז''ל שאין נאה ליוצא ונכנס וכו'. ומטעם זה הקדים התואר למתואר להסמיך המעלה לצד היותם כהנים מה שלא היה נשמע כן אם היה אומר אמור אל בני אהרן:
@1 **ואמרת אליהם לנפש וגו'**. צריך לדעת למה כפל לומר **ואמרת**. ורז''ל אמרו (תו''כ יבמות קיד:) כמה דרשות, ועוד יש לאלוה מילין והוא על דרך מה שכתב הרמב''ם פרק ב' מהלכות אבל וזה לשונו המטמא את הכהן אם היו שניהם מזידים הכהן לוקה וזה המטמא עובר משום ולפני עור וגו', ואם היה הכהן שוגג והמטמא מזיד הרי זה שמטמאו לוקה ע''כ. וקשה מנין לו להרמב''ם לחייב המטמא מלקות, והרב המגיד ומהרי''ק לא אמרו כאן דבר, כי אם הלחם משנה אשר הוא כתב וזה לשונו בהלכות כלאים כתב רבינו בזה שהמלביש כלאים לחברו אם היה הלובש שוגג המלביש לוקה, ותמה עליו הכסף משנה וכתב ששאל זה הרא''ש מהר''ש ולא זכינו לתשובה וכו', ואפשר לו דמשמע ליה לרבינו דמדאמרינן בפרק ג' מינים (נזיר מד.) דגלי קרא בנזיר שלא עשה המטמא כנטמא מדכתיב וטמא את ראש נזרו משמע דבעלמא עבדינן המטמא כנטמא ולכך כתב רבינו בפרק ה' מהלכות נזירות שאם היה הנזיר שוגג וזה שטמאו מזיד אינו לוקה ע''כ דברי הרב, ואינם נראים דקשה א' למה לא יהיה הנזיר בנין אב לכל התורה כולה דלא אמרינן המטמא כנטמא וכו' וכן על זה הדרך. ועוד ההוא דנזיר שהוצרך הכתוב למעט משום שהייתי דן קל וחומר מתגלחת שחייב דהא חומר בטומאה מבתגלחת תלמוד לומר וטמא את ראש וגו' ע''כ, אם כן זולת הקל וחומר לא היה צריך למעט, ואדרבא תגדל מדורת הקושיא לרמב''ם מההוא דפרק ג' מינים:
@1 **והנכון** בעיני שטעמו של רמב''ם הוא מאותה שאמרו במסכת נזיר דף מ''ד וזה לשונם ומה טומאה וכו' לא עשה בה מטמא כמיטמא תגלחת לא כל שכן שלא עשה מגלח כמתגלח אמר קרא תער לא יעבור קרי ביה לא יעבור הוא ולא יעביר לאחר עד כאן ופירש''י לא יעביר לו אחר ע''כ, פירוש אזהרה לאחר שלא יעביר תער על ראש הנזיר שאם לא כן תהיה הכוונה שלא יעביר הנזיר שער של אדם אחר ופשוט. וצריך לדעת כוונת הש''ם מנין דורש לא יעביר לו אחר, אם דורש המסורת הלא מסורת לא יעביר הוא ביו''ד בין בי''ת לרי''ש. ועוד לכשנאמר שאין חסרון היו''ד מעכבת אף על פי כן עדיין חסר תיבת לו שזולתה יהיה משמעות לא יעביר שהנזיר לא יעביר לאחרים:
@1 **אכן** כוונת הש''ם שמדייק מאמר הכתוב תער לא יעבור וגו' שהיל''ל לא יגלח את ראשו או לא יעביר על ראשו יו''ד בין בית לרי''ש ויחזור אל הנזיר האמור בסמוך ויתלה האיסור כמצווה עליו לא במעשה התער שלא בכינוי אל המתגלח כאומרו תער לא יעבור שמשמעות הדברים יגידו שאסר המעשה בין על יד המתגלח בין על יד אחרים, והוא מאמר הש''ס קרי ביה לא יעבור הוא ולא יעביר לו אחר פירוש משמעות התיבה תגיד לאסור הדבר בין על ידו בין על ידי אחר. ומאמר קרי ביה אינו מדויק אלא מלבישים המכוון בתיבה והבן. ומעתה כמו כן נאמר בדין כלאים שאמר (לעיל יט יט) ובגד כלאים שעטנז לא יעלה עליך ולא אמר לא תעלה עליך משמע שלא על המעלה עליו לחוד מצוה אלא על המעשה הוא מצוה שלא יהיה בין ממנו בין מהזולת, ולזה פסק הרמב''ם (הל' כלאים פ''י הל''א) שהמלביש כלאים לחבירו מזיד לוקה, וכמו כן נאמר במה שלפנינו בטומאה כהן ממה שאמר הכתוב לא יטמא אזהרה שלא בכינוי לנטמא לומר שמזהיר בין לכהן עצמו בין לאחרים על הטומאה. ושיעור המצוה היא שמצוה ה' ב''ה לבל יהיה הכהן טמא. ומעתה כל המטמאו בין הוא בין אחר הרי זה עבר על הלאו ולוקה. וכפי זה עלו פסקי רמב''ם על נכון:
@1 **ובזה** נבוא ליישב דקדוק הכתוב שכפל לומר אמור ואמרת, כי לצד שצוה ה' לכהנים גם לאחרים על טומאתם, כנגד הכהנים אמר אמור אל הכהנים, וכנגד אזהרת אחרים שלא יטמאו אמר **ואמרת** אליהם. ואולי שתיבת אליהם חוזרת לישראל המצטוים בכל המצוה, ותמצא שאמר בסוף ענין זה (פסוק כד) וידבר משה אל אהרן ואל בניו ואל כל בני ישראל הרי שהציווי נאמר מה' גם לישראל, וזה יצדיק לך פירושנו שהאזהרה בא כאן גם לישראל שלא יטמאו הכהנים. ובתורת כהנים (לקמן כד) אמרו וזה לשונם וידבר ה' הזהיר את אהרן על ידי הבנים ואת הבנים על ידי ישראל ואת הבנים זה על ידי זה, ואלו ואלו דברי אלהים חיים:
@1 **לנפש**. רז''ל דרשו (בתו''כ) לרבות רביעית דם וכו', וראיתי לרמב''ם ז''ל שכתב בפרק ג' מהלכות אבל וזה לשונו אחד המת ואחד שאר הטומאות הפורשות מן המת שנאמר לנפש עכ''ל, והקשו עליו מדתנא בתורת כהנים וזה לשונם אין לי אלא המת מנין לרבות הדם תלמוד לומר לנפש, מנין לרבות כל הטומאות הפורשות מן המת תלמוד לומר ואמרת אליהם לרבות וכו' ע''כ. ותירץ הכסף משנה שסובר רמב''ם שמתיבת לנפש גמרינן הכל ששקולים הם וקרא לא צריך אלא אסמכתא ע''כ. ואין דברי הכסף משנה נראים, כי מנין לו לרמב''ם לבנות בנין חדש שלא כדברי הברייתא:
@1 **אכן** הנכון הוא כי רמב''ם ז''ל ברייתא אחרת הוא שראה והנה היא כתובה בפסיקתא, וזה לשונם אמור ואמרת להזהיר גדולים על הקטנים, לנפש לא יטמא להביא רביעית דם שתצא מן המת שהוא בלא יטמא עכ''ל, והובאה ברייתא זו ביבמות (קיד.). ולפי ברייתא זו תתחייב לומר שגם שאר טומאות הפורשות מן המת מתרבות מן לנפש שהרי דורש כפל ואמרת להזהיר גדולים על הקטנים. והדבר פשוט אצלי שנעלמה ברייתא זו מעיני הכסף משנה והראיה שכתב הרב בפרק הנזכר דין י''ב וזה לשונו כהן קטן וכו' הגדולים וכו' כפירש''י אמור ואמרת וגו' עד כאן, הנה ממה שמוכיח דין זה מדברי רש''י ולא מדברי הברייתא אתה יודע שלא ידע הברייתא:
@1 **ונשאר** ליישב מנין להם לדרוש מתיבת לנפש רביעית דם וכו', ודלמא הוצרך לומר לנפש להודיע שאינו מזהיר אלא על טומאת מת ולא על שאר טומאות, ויש לומר שהיה לו לומר למת לא יטמא ומאומרו **לנפש** דרשו רביעית דם וכל שיש בו נפש. אבל טמאי מת אינם בכלל זה:
@1 **לא יטמא**. אמר לשון יחיד הגם שהתחיל לדבר בלשון רבים הכהנים, אליהם. לסברת תנא שדרש כפל ואמרת להזהיר גדולים על הקטנים מעתה אין לנו מקום אזהרה למטמא שלא יטמא לכהן לזה אמר לשון יחיד ואמירה לרבים לומר שאזהרת רבים על היחיד הא למדת אזהרה למטמא:
@1 **עוד** נראה שחש הכתוב לומר לא יטמאו שלא תבא הסברא לטעות שלא הקפיד הכתוב אלא על טומאת כללות הכהנים, כי דבר זה אינו אלא חוקה ואין לנו אלא מה שבא בפירוש, אבל כהן יחיד לא יקפיד עליו תלמוד לומר יטמא לשון יחיד. עוד לצד שצוה ה' לכהנים (לעיל י ט) איסור יין ושכר ושם גילה הכתוב שטעם האיסור הוא לבל יעבדו עבודת הקדוש שתויי יין, ואם כן שלא בזמן משמרתם או שלא בזמן עבודה יכולין לשתות יין ושכר, ואם כן תבא הסברא שילמוד סתום מהמפורש לדון בטעם איסור טומאה שהוא מהטעם עצמו שנאסרה שתיית יין ושכר נאסרה טומאה כדי שיהיה ראוי לעבודה לזה נתחכם ה' וידבר לשון יחיד לא יטמא לומר שאפילו אחד מהכהנים הוא עומד באיסור זה, וממוצא דבר אתה למד שלא מטעם ביטול עבודה כי אין עבודה בטילה מהעדר כהן אחד, אלא ודאי שאיסור טומאת כהן היא חובת גברא ואפילו מי שמשמרתו באה לזמן רחוק אף על פי כן הוא באיסור זה, ומטעם האמור בדבריהם ז''ל וכתבנוהו למעלה:
@2 **כי אם לשארו וגו'** תניא בתורת כהנים וזה לשונם שארו זו אשתו דכתיב שאר אביך, הקרוב למעט ארוסה פירוש לצד שעדיין לא נתקרבה. אליו למעט הגרושה פירוש קרוב שנתרחק. יאמר לאמו מה תלמוד לומר לאביו מה אמו שהיא מתחללת הרי הוא מטמא לה אביו שאינו מתחלל אינו דין שיטמא לו אלו כן הייתי אומר מה אמו בידוע אף אביו בידוע אביו חזקה מנין תלמוד לומר ולאביו ע''כ. הקשו חכמי לוניל לרי''ץ לעולם לא יאמר הכתוב לאביו ואנו למדין מקל וחומר מאמו מה תאמר הרי אביו זה אינו ידוע כאמו יטמא ממה נפשך אם זה אביו מטמא ואם אינו אביו אם כן הוא ממזר ואין לו כהונה עד כאן. ובעיני אינו קושיא כלל כי הכתוב כאן בא לב' דברים להתיר, ולהצריך, להתיר טומאה בקרובים הגם שאסר ברחוקים, ולהצריך. שאם לא רצה ליטמא מטמאין אותו בעל כרחו, כמו שאמר הכתוב לה יטמא ואמרו בתורת כהנים מצוה, שחייב כל כהן ליטמא למתים האמורים בענין. והגם שלא נאמר לה יטמא אלא באחותו, הרי אמרו בתורת כהנים וזה לשונם מעשה ביוסף הכהן שמתה אשתו בערב פסח ולא רצה ליטמא לה ודחפוהו חכמים וטמאוהו בע''כ עכ''ל, הרי שלך לפניך שעל כל הקרובים האמורים בענין הוא חייב ליטמא. וכפי זה אם הייתי דן טומאת אביו מדין ממה נפשך אין לי מקום לחייבו לטמא לו כי יאמר מי יאמר שהוא אביו, ומה גם אם ימות אביו בערב פסח אין לבטל מצות פסח א' במועדו מחמת ספק, ולא מבעיא למאן דאמר (רמב''ם ופר''ח) ספק דאורייתא מותר מדאורייתא פשיטא שלא יטמא לדחות מצות פסח במועדו אלא אפילו למאן דאמר ספק דאורייתא אסור מדאורייתא אף על פי כן אין לו לדחות מצות ודאי מפני מצות ספק, תלמוד לומר לאמו ולאביו שחייב ליטמא לכל אחד מהם דבר תורה. ועיין בפסוק שאחר זה:
@2 **ועוד** נראה לי כיון שיש מציאות שאביו אין לו אלא חזקה, והבן מוחזק בכהן, כגון שיש לפנינו ב' בני אדם מוחזקים בחזקת כהנים כל אחד בפני עצמו, גם מוחזקים שאחד מהם אב ואחד בנו, ומציאות זה יכול להיות שיורע חזקת האב שאינו כהן ולא יורע חזקת הבן להסירו ממדריגת כהן ונאמר שאין זה אביו ונשאר הבן בחזקתו. וכיון שכן אם לא אמר לאביו הייתי דן שלא יטמא לאביו חזקה באופן הנזכר מטעם שמא יורע חזקת אביו והבן ישאר כהן לעולם, ולזה אמר התנא אביו חזקה מנין תלמוד לומר לאביו. והנה בין לדרך זה ובין לדרך ראשון אביו חזקה חייב לטמא לו כי סוף כל סוף אביו אינו אלא חזקה והתורה חייבתו ליטמא:
@2 **ולבנו ולבתו ולאחיו וגו'**. תניא בתורת כהנים וזה לשונם יאמר לבנו ולבתו מה תלמוד לומר לאמו ולאביו. בנו ובתו שאינו חייב בכבודם הרי הוא מטמא להם אביו ואמו שהוא חייב בכבודם אינו דין שיטמא להם, אלו כן הייתי אומר לבנו ולבתו הנפלים, תלמוד לומר לאמו ולאביו מה אמו ואביו בני קיימא אף בנו ובתו בני קיימא ע''כ. קשה כפי זה לא היה צריך לומר אלא לאמו ולבנו וגו' ולא יאמר לאביו, ולטענת מה אמו בידוע, בנו ובתו יוכיחו שמן הסתם אינם בידוע אלא חזקה ומטמא להם. ואין לומר שגרוע אביו מבנו ובתו, שהרי מצינו שדן התנא קל וחומר מהם לאביו ולאמו, ואם כן למה הוצרך לומר לאביו. ואם לגלות על בנו ובתו שהם בני קיימא, למדינן מיתור לאמו שאין צריך שבאה מק''ו בנו ובתו, ואין לומר שצריך לאביו ולאמו שניהם יחד למעט בנו ובתו הנפלים, כי למה לא יספיק אחד. ועוד אם צריך שניהם מה מקום לתנא לעשות צריכיות בין לאביו ולאמו הלא צריכין שניהם למעט בנו ובתו נפלים, והדברים פשוטים:
@2 **ונראה** לומר שאם לא אמר לאביו הייתי דן על זה הדרך מה תלמוד לומר לאמו בנו ובתו שאינו חייב בכבודם מטמא להם אמו לא כל שכן, אילו כן הייתי דן גם אביו תלמוד לומר לאמו למעט אביו מטעם שאינו אלא חזקה, והיינו מתחייבין לפרש כי בנו ובתו שאמר הכתוב הם דומים לאמו בידוע, וכגון שלא היה מציאות שתתעבר אשתו אלא ממנו על ידי ידיעה ברורה במציאות שיכול להיות, מה שאין כן אחר שאמר הכתוב לאביו והקשינו למה הוצרך ויבא דינו מאמו והכרחנו לומר שבא לומר אפילו אינו אלא חזקה אם כן אמו למה לי שמע מינה למעט בנו ובתו נפלים. והגם שהתנא אמר לאביו ולאמו למעט הנפלים, לאו דוקא, וסמך על מה שהעירך בסמוך בדרשת לאביו שבא לומר אפילו אינו אלא חזקה:
@2 **אלא** שקשה למה שאמרו שם בתורת כהנים בסיפא דברייתא דלאמו ולאביו וזה לשונם אלו נאמר לאביו ולא נאמר לאמו וכו' הייתי אומר מה אביו שאינו מתחלל אף אמו שאינה מתחללת אמו שנתחללה מנין תלמוד לומר לאמו ע''כ. הרי שהוצרך לאמו לרבות אפילו נתחללה, ומנין לו למעט הנפלים, ואם תדרוש לנפלים נתחללה מנין, ועוד צריך לדעת כפי זה בתו שנתחללה אם חייב לטמא לה או לא, שיש פנים לומר דוקא אמו שחייב בכבודה הוא שנתרבית אפילו נתחללה, ויש פנים לומר כיון שגילה קרא שהחילול אינו פוגם הקורבה הוא הדין בתו:
@2 **אכן** בהעיר בדברי התנא מנין מצא לומר שיטמא לאמו שנתחללה, אם מיתור, דלמא אצטריך משום שהייתי אומר לאביו לצד שיש בו מעלה שאינו מתחלל מה שאין כן האם שגרועה מערך אב לצד שמתחללת. וכמו כן דקדק התנא בתחלת דבריו באמרו מה אביו שאינו מתחלל, משמע כי ההפרש יוצרך לעשות בו ההדרגה הגם שאינו בנמצא אלא כיון שראוי להיות, ואם כן נוכל לומר עד עתה שאמו שנתחללה פטור מלטמא, ובהכרח לומר שהתנא סובר כי אומרו לאמו משמעותה הוא בין כהנת בין חללה. האמת שאם לא היה אומר אלא לאביו היה לבעל דין לחלוק ולומר אמו גרועה מאביו גם בהיותה כהנת כיון שישנה בחילול, אבל אחר שאמר לאמו אפילו נתחללה במשמע. וכמו כן תדון כשאמר הכתוב ולבתו אפילו נתחללה במשמע. כי לא תלה הכתוב הדבר אלא בסיבת הקורבה, ואמו שנתחללה ובתו שנתחללה נקראים אמו ובתו, ומעתה כיון שבלא ריבוי אנו אומרים כי משמעות בתו הוא אפילו שנתחללה כל שנקראת בתו יטמא לה, אם כן נבא לדין למה אמר אמו והלא תבא בקל וחומר מבתו ומה בתו שנתחללה מטמא לה אמו אצטריך:
@2 **אכן** אם לא אמר הכתוב לאמו אז לא היינו אומרים כי לאביו בא למעט בנו ובתו הנפלים אלא למעט אמו, ומיעוט זה קרוב יותר בנשמע מלילך לחפש אחר הנפלים של בנו ובתו לומר שעליהם בא, והייתי ממעט אמו מטעם שמתחללה, וכשהיינו באים לדון מבתו שמתחללת ומטמא לה היינו מעמידין מיעוט האם כשנתחללה דוקא, אבל לא נתחללה היתה באה מקל וחומר מבתו, וכשנבוא לדון בבתו אפילו נתחללה ממשמעות התיבה כמו שאמרנו למעלה שאפילו נתחללה תקרא בתו, היינו חוזרים ודנים בתו שנתחללה מאמו שנתחללה ומה אמו שנתחללה אינו מטמא לה כמו שדרשנו מיתור לאביו בתו שנתחללה לא כל שכן והגם שמשמעות בתו יגיד אפילו נתחללה, זה מן הסתם, אבל כשיבא הלימוד במיעוט או בקל וחומר נחזור להעמידה בשלא נתחללה:
@2 **העולה** מכל הכתוב בעומק הכתוב הוא, שאם לא אמר הכתוב לאביו שממנו נבא לטעות שבא למעט אמו כמו שכתבתי לא היה צריך לומר לאמו והיתה באה מבנו ובתו כנזכר. ואם לא אמר לאמו שממנה היה בא הטעות לומר שבא למעט אביו לצד שאינו ידוע אלא חזקה לא היה צריך לומר לאביו. אם כן תקשה לא יאמר לא אביו ולא אמו לזה דרשו שבא למעט הנפלים שאינו מטמא להם, ומעתה אין מקום לנו לומר שיאמר או לאמו לבד או לאביו לבד, כי אחד מהם שיאמר יוליד הטעות ויסתור הבנין, ונתחכם ה' לדבר דברי אמת, ולזה נתחכם התנא וקדם להודיע הטעות היוצא מאם יאמר א' מהם, ואחר כך דרש יתור שניהם יחד והבן. ובזה עלה דברי התנא לאור עולם דברי אלהים חיים:
@8 **וקדשתו** ולא אמר וקדשתם כסדר הנדבר עד עתה בלשון רבים. לדבריהם ז''ל (יבמות פח:) שאזהרה זו באה שאם כהן לא רצה לגרש אשה זונה וחללה וגו' שמלקין אותו ומיסרין אותו עד שיגרש, ולפי הטעם שנתן הכתוב **כי את לחם אלהיך הוא מקריב**, תבא הסברא לומר כי כל עוד שיש כהנים שלמים וכן רבים המספיקים להקריב אין חיוב לכוף, לזה אמר לשון יחיד שאפילו על אחד מהם יקפיד לעשות כמשפט הזה:
@8 **קדוש יהיה לך**. פירוש כדי שיהיה קדוש יהיה לך הכהן פירוש הנה הוא שלך לכופו על הדבר. ואומרו **כי קדוש**, פירוש לצד שקדמה לנו הידיעה כי הקדושה היא בחינה הנקנית ברצון ובהשלמת החפץ והחשק בה ולא בכפייה. ואיך אומר הכתוב לכופו על הקדושה, לזה אמר **כי קדוש** פירוש לא להמשיך לו הקדושה מחדש שכבר הוא קדוש אלא שלא לאבד קדושתו. ואומרו **אני ה' מקדשכם**, נותן טעם לחיוב ישראל בדבר זה, כי באמצעות קדושת כהן ה' ב''ה משרה שכינתו בתוכינו ומקדש אותנו, ואם אין כהן אין עבודה ואין מקדש ואין שוכן:
@17 **דבר אל אהרן לאמר**. אמר לאמר, לצד שהמצוה באה לאהרן כאומרו דבר אל אהרן שהטיל עליו להפריש בעלי מומין מהכהנים להיות שהוא כהן גדול, לזה אמר **לאמר** שיזהיר גם כן כל הכהנים שיאמר להם המצוה, ונמצאו מוזהרים הכהנים על עצמן וכהן גדול גם כן מוטל עליו לבל [יגש] (יזיד) איש בעל מום:
@17 **איש מזרעך וגומר**. לא אמר כסדר שאמר בתחלת הפרשה, ולא כסדר שאמר בפרשה שאחריה דבר אל אהרן ואל בניו וינזרו, ולא כסדר יין ושכר שאמר אתה ובניך. ואולי כי נתכוין ה' במתק לשונו לומר שאהרן ובניו מובטחים מכל המומין האמורים בפרשה לזה לא הזכיר לא הוא ולא בניו אלא זרעך. והגם שגם בניו יקראו זרעך, אף על פי כן ממה ששינה העירך כי על הבאים אחריהם הוא אומר, ודקדק גם כן לומר מזרעך, הבטיחך שלא יפול המום בכולם אלא במקצתם, ועיין בפירוש פסוק והוא צרוע (לקמן כב ד):
@21 **כל איש וגו' מזרע אהרן וגומר**. כפל האזהרה הוא לישראל שלא יניחו להקריב בעל מום, ולזה לא עשה הציווי לנוכח והבן:
@27 **אמור אליהם**. בתורת כהנים אמרו וזה לשונם אליהם אלו העומדים לפני הר סיני ע''כ. הוקשה להם יתור אמור אליהם אם על האמורים בסמוך שהם הכהנים, לא היה צריך לומר, שעליהם התחיל לדבר וזה גמר המצוה שהתחיל לדבר בה. ואם על ישראל הלא לא הוזכרו בסמוך לזה אמר על העומדים בהר סיני, כי שם נזדווגה אומה לאלהיה וכשידבר סתם הדבר מובן שעליהם הוא אומר, וכפי זה הרי עונש זה הוא גם לישראל, ואם תאמר אם כן למה בכל התורה מזכיר בני ישראל בכל פרט ופרט ולא הספיק לומר דבר אליהם, כבר אמרו ז''ל (ויק''ר פ''ב) משל למי שהיה לו בן חביב ותמיד זכרונו בפיו אכל בני שתה בני, כמו כן הקב''ה לאהבת ישראל ערב עליו זכרונם בפיו. ובמקום שיש לדרוש דרשינן:
@28 **מזרע אהרן**. הוצרך להזכירם פעם ב', לומר שהם דוקא הוא שישנם בהערב שמש, אבל קדשים שאוכלים ישראל שהם (השלמים) [מע''ש] אין צריכים הערב שמש כך דרשו בתורת כהנים. ואומרו **והוא צרוע**, דרשו בתורת כהנים וזה לשונם אין לי אלא זרעו עצמו מנין תלמוד לומר והוא וגומר עד כאן. הנה בדין זה אי אפשר לומר מה שפירשנו בפסוק (כא ז) איש מזרעך כי ה' ישמרנו, לצד שיש כאן גם כן אשר תצא ממנו שכבת זרע, ואהרן מצינו שלא פירש מאשתו, ואם לא היה אומר והוא היה מקום לומר שאהרן יאכל הקדשים בטומאה תלמוד לומר והוא, וכיון שנתרבה אהרן נתרבו גם כן בניו, ומעתה פסוק ראשון שאמר איש מזרעך אשר יהיה בו מום ולא נתרבה אהרן אמור מעתה שאינו בכלל, והוא מטעם שהוא מובטח שישמרהו ה' לו ולבניו שלא יפול בהם מום, וכמ''ש:
@36 **ובת כהן וגו' היא וגו'**. בתורת כהנים דרשו מיעוט היא לאמה שאמה אוכלת מצדה הגם שהיא אינה אוכלת ואפילו נתאלמנה אמה. וראיתי להעיר לבות בני אדם ברמז גדול אשר רמזה פרשה זו. דע כי אמדו ז''ל (סנהדרין צג.) שעם בני ישראל הדרגתם למעלה מהדרגת המלאכים. ואמרו עוד (זוהר ח''ב קנה.) כי ה' ברא ד' עולמות זה למעלה מזה, ורשומים המה בפסוק (ישעי' מג) כל הנקרא בשמי ולכבודי בראתיו יצרתיו אף עשיתיו. לכבודי עולם עליון הנקרא אצילות, בראתיו הנקרא עולם הבריאה, יצרתיו יצירה, עשיתיו עשיה, עוד יש לך לדעת כי כבודו יתברך מלא כל עולם ועולם ועד מתחת עולם דכתיב (דברים לב ט) ומתחת זרועות עולם, ואורו יתברך מאיר בד' עולמות, הוא בסוד ד' אותיות שם הוי''ה ב''ה, יו''ד בעולם האצילות, ה''א ראשונה בעולם הבריאה וכו', ואמרו ז''ל (זוהר ח''ג ריח:) שחיונית המתנועע בבני אל חי הוא מאורו יתברך דכתיב (דברים לג כז) כי חלק ה' עמו. גם קראם ה' בניו:
@36 **עוד** אמרו ז''ל (זוהר ח''א פ: צד:) כי בחינות החיוני שבאדם יתייחס אליו ד' כינויים, יש שיקרא נפש, ויש שיקרא רוח, ויש שיקרא נשמה, ויש שיקרא חיה, בסוד כי רוח החיה באופנים, ותקרא נשמה לנשמה. ואמרו אנשי אמת כי בחינה הבאה מאור עולם העשיה לצד היותו מועט ואין בו אלא כל שהוא מהחיונית המנענע, והוא הוא שמרגיש במורגשות עולם הזה, ועשה ה' ככה לסיבת העולם להיותו גס, וזו תקרא נפש, והבא מאור עולם היצירה לצד היותו עליון מעולם העשיה הארתה גדולה ותקרא רוח, והבאה מאור עולם הבריאה תקרא נשמה לצד הדרגתה, והבאה מאור עולם האצילות תקרא נשמה לנשמה:
@36 **והנה** האדון ה' צבאות עשה התקשרות כל העולמות רוחני וגשמי באדם ישר קשר כל הגשמיות וכל הרוחניות יחד, הגשמיות בנה ד' יסודות ושם שם לו חק הרוחניות מכל העולמות. ויש לך לדעת כי הגשמיות יתנגד לחיבור הרוחני יותר מהתנגדות אש ומים, לזה נתחכם ה' ב''ה וברא באדם מכון הראשון שהוא הנפש שאין בה אלא חלק מועט מהרוחניות והשרה בתוכה בחינה עליונה ממנה שהיא בחינת הרוח, ונמצאת הנפש ממוצעת בין הגוף ובין הרוח, כי אין הרוח עומד בגשם בלא אמצעיות הנפש, וכמו כן הרוח ממציע בין הנפש והנשמה, כי הנפש בערך הנשמה שאורה רב כגוף לערך הרוח, וכן נשמה ממצעת בין הרוח ובין נשמה לנשמה נמצאת אומר כי הנפש יכולה עמוד לבדה, והרוח בב', והנשמה בג', ונשמה לנשמה בד':
@36 **עוד** אמרו יודעי דעת קדוש (זוהר ח''ב צד:) כי התעצמות השלמים באמצעות לקח טוב אשר נתן לנו הבורא הוא לעלות מדרגה התחתונה למדרגה שלמעלה ממנה, על זה הדרך נפש יעלה למדרגת רוח, ורוח למדרגית נשמה, ונשמה למדרגת נשמה לנשמה, וזו היא תכלית סיבת בריאת האדם תן לחכם ויחכם:
@36 **עוד** אמרו ז''ל כי ההשגה בהעלאה זו תסובב שישלח אדם ידו ויהנה כאדם העושה בשלו, והוא סוד (תהלים קכח) יגיע כפיך כי תאכל אשריך וטוב לך, פירוש האושר שלך והטוב שלך, והוא מאמר חז''ל שהנפש קודם ביאתה לעולם הזה אוכלת כבת בוגרת, ובחזרתה כבת נשואה. עוד יש לך לדעת כי כל אשר יצר וברא ועשה ה' הכל עומד למזון ולמחיה מעולם העליון שאליו יקרא עולם האצילות, והוא אור היו''ד שבשמו יתברך, והמזון ההוא יקרא קודש, והוא מקור החיות והאושר והטוב, והגם כי כל הנבראים יורד להם החיות, כי זולת החיות אין נברא, והוא סוד אומרו (נחמיה ט) ואתה מחיה את כולם, על כל זה ישתנה השפע בהתרחקותו, כאשר ישתנה הצומח מן הארץ כשמתרחק מהיניקה, ועשה ה' ככה לתת לכל אחד כפי בחינתו וכפי אשר ישיג בטהרתו, גם לארץ הגשמית יתן לה ה' מים וזהו שפעה וחיותה והולידה והצמיחה. ועל דרך זה גם כן הוא שפע החיוניות של הנפשות והרוחות והנשמות ונשמות לנשמות כפי בחינתה, כי לא כל הנפשות בהדרגה א', ולא כל וכו' שוות וכו', ואין לך נברא בין בגשמיים בין ברוחניים בין במלאכים העליונים בין בנפשות רוחות (כוחות) נשמות נשמות לנשמות שאינם צריכין לשפע הקדוש, אלא כל א' כפי שורשו הקדוש:
@36 **עוד** יש לך לדעת כי להיות שיש אדם שזוכה לכל המדרגות הקדושות, ויש שזוכה לג', ויש לב', ויש לאחד, ומי שלא זכה אלא בנפש בעולם הזה ולא לרוח אין מעשיו מועילים כלום, כי אין כח בידו להשיבה למעלה, כי אין מחזיק בידו להטותה אלא באמצעות הרוח אם יזכה לרוח באמצעות מעשיו הטובים יעלה הנפש למדרגת הרוח. ודע כי כאשר יעלנה למדרגת הרוח הנה הוא קנאה במעשיו ונקרא הוא בעלה, והוא סוד אומרו (משלי כג) אם בעל נפש אתה פירוש קנאה והוא שלו באמצעות היגיעה, והמושג מהיגיעה נעשה הרוח בעל נפש כי עולה היא עמו ושוים הם בהדרגה ומקום תחנותו תחנותה מפתו תאכל ומכוסו תשתה ובחיקו תשכב, וכן הרוח בערך הנשמה, והנשמה בערך נשמתה, וקניית מדרגת בחינת הקדושות הלא הוא באחד מב' סיבות, או מצד המזריע כי האב יפעיל כח עליון בבן כמו שפירשתי בפרשת ויחי (מט ג) בפסוק ראובן בכורי. או לצד התעצמות באמצעות עסק התורה, וכמו שכתב בזוהר הקדוש (ח''ג צא:) בפרשת שור או כשב או עז כי יולד כי האדם יכול להשיג מה כפי התעצמותו בתורה וכו' אפילו יהיה במדרגה שאין למטה ממנה אם יטריח ישיג הדרגות עליונות כפי שיעור היגיעה יעיין שם דבריו:
@36 **עוד** יש לך לדעת כי המסובב מחטא האדם גם כן ישתנה כפי מה שהיא בחינת האדם, כי אינו דומה פגם אשר יסובב לנפש כפגם הרוח ושאר הדרגות, כי פגם הנפש יסובב כליונו בסוד (יחןקאל יח) הנפש החוטאת היא תמות, ופגם הרוח אפילו לא יסובב אלא כתמים ונגעים יחשב פגם גדול, ולזה יצוה ה' עליו והרוח תשוב אל האלהים אשר נתנה ודרשו רז''ל (שבת קנב:) תנה לו כמו שנתנה לך, שזולת זה נדבקים בה סרכי הטומאה ויסבוה לגיוני הסטרא אחרא וימנעוה משוב אל מקומה הראשון. ופגם הנשמה הגם שלא יגיעה כשיעור הנזכר אלא יפחת אורה ממה שהיה תכסהו כלימה, כי הכל כפי המבייש והמתבייש. ופגם נשמה לנשמה הגם שלא יגיע עליה מהפגם ולא הפחתה אורה אלא שיסוכב שתצא ממנו שלא כרצונה, כמו שאמרו בתיקונים (תיקון ע') בסוד פסוק לא יאונה לצדיק כל און שמדבר הכתוב במי שיש לו נשמה לנשמה וכשבא אדם לידי חטא מסתלקת הנשמה הקדושה שלא יאונה לה און, וסילוקה זה תקפיד עליו כפי ערך מעלתה, הא למה הדבר דומה למאכסן מלך בביתו וחוזר בו ומגרשו:
@36 **ואחרי** הודיע ה' אותנו כל האמור נוכל לומר כי הן הנה הדברים האמורים בכתובים. והתחיל לומר **וכל זר לא יאכל קודש** מדבר בב' עניני קודש, בקודש הקרבנות, ובקודש הנעלם שהוא שפע הרוחני מזון לבני אלהים. ואמר **תושב כהן ושכיר** לרמוז אל הרוח ואל הנפש, כי הרוח הוא תושב כהן פירוש כי בו מושב הנשמה הנקראת כהן שהיא מדרגה העליונה, ושכיר גם כן הוא הנפש כי הוא הפועל כל מלאכות האדם, ב' בחינות אלו הודיע הכתוב שאינם ראויים לאכול מהמזון הנקרא קודש לצד היותו מדרגה גדולה, וצא ולמד מה שכתב הרשב''י (זוהר ח''ב קכא) בהפרש שבין קודש לקודש. ואמר **וכהן כי יקנה נפש** וגו' פירוש כהן היא נשמה העליונה תקרא כהן. והזכירה בלשון זכר לומר כי כיון שהגיעה לגדר זה תקרא במדרגת זכר, כי יקנה נפש כי באמצעות כשרון מעשיה קנתה גם הנפש והעלתה אותה למדרגתה ותקרא בעל נפש.
@36 **הוא יאכל בו** פירוש כי יזכה ליהנות גם הנפש מקודש מה שלא היה זה קודם עלייתה, ואמר הנפש ומכל שכן הרוח שהוא עליון מנפש. ואומר **ויליד ביתו** יכוין אל נפשות הקדושה אשר נפלו מזמן קדמון והם מתבררים באמצעות כשרון מעשה הצדיקים, שהמעשה הטוב הוא כאבן השואבת להוציא ניצוץ הטוב, ויתיחסו בשם ילידי הנשמה המבררתם, ואמר הכתוב שגם הם יעלו עמה ליהנות מקודש:
@36 **ואומרו** ובת כהן מדבר הכתוב בנשמה שנפגמה ונטמאה במעשיה שתפסיד הנאת הקודש והוא אומרו **ובת כהן** שהיא הנשמה, **כי תהיה לאיש זר** שהוא ס''מ שחמדה מטעמותיו ותזנה אחריו, היא בתרומת הקדשים לא תאכל, דקדק לומר בתרומת, לומר שאפילו תרומת הקדשים לא תאכל תרי ממאה, ואין צריך לומר הקודש עצמו. ודקדק לומר היא לשלול אחרת הבא משפטה בסמוך, דכתיב ובת, וזה הוא עינוי הנפש כשיחסר מזונה היא נשפלת ונחשך אורה וירד הדרה רחמנא ליצלן:
@37 **ואומרו ובת כהן כי תהיה אלמנה וגו'**. מדבר הכתוב בבחינת נשמה לנשמה שאין מגיעה דביקות הרע כל עיקר אלא שהיא בורחת והולכת לה כמו שאמרנו, והוא מה שנתן טעם בבת כהן תנשא, לומר כי בחינה זו מעולה ביותר, ולזה אין זר אתה כמו שאמרנו שעליה נאמר לא יאונה לצדיק וגו'. וקורותיה הם שתהיה אלמנה וגרושה אמר אלמנה כאשה שאין לה בעל הזן ומפרנסה כמו כן בעלה לא זן ולא מפרנסה במצוות ובמעשים טובים **וגר** ושה כי לצד שפשט ידו האדם לעבור פי ה' גרשה ממנו כמו שכתבנו, **וזרע אין לה** שלא עשה פירות בעולם הזה, אף על פי כן **ושבה אל בית אביה** וחזרתה היא לאכול משלחן אביה כימי נעוריה שהיתה אוכלת בבושה מלחם אביה תאכל, מה שאין כן נשמה שהשיגה עשות תורה ומצות שאוכלת יגיעה כאדם האוכל משלו. ואומרו **וכל זר לא יאכל קודש** נתן טעם למה אין ה' מרחם גם לנשמה להאכילה קודש בתורת חן וחסד, לזה אמר הטעם הוא וכל זר וגו', ולזה נשמה שנדבק בה בחינת הרע הנקרא זר לא תאכל לבל יאכל הזר ההוא הנדבק בה:
@38 **ונתן לכהן את הקודש**. רז''ל נחלקו בפרק ו' דתרומות רבי אליעזר אומר כל שראוי להיות קודש, ור''ע אומר הקודש שאכל ע''כ, ואולי שיכוין לומר שעל ידי הנתינה זו מעלה עליו הכתוב כאילו נותן הקודש עצמו, וכאילו לא אכל הקודש:
@40 **והשיאו אותם** וגומר. פירוש כשלא יפרעו קרן וחומש יגדילו גדר האשם שעשו בשוגג ליקרא מזיד שהוא עון כיון שיש בידם נתקן ואינם מתקנין, והוא אומרו **והשיאו** פירוש ינשאו אותם פירוש הם שיהיה הדבר עון את שאינה אלא אשמה. ואו **מרו באכלם את קדשיהם** פירוש שיחשב להם מזיד אכילת הקדשים שאכלו לא הזדת מניעת הפרעון, ועיין מה שפירשתי בפסוק שלפני זה:
@59 **מועדי ה' וגו'**. גזירת הדיבור. רז''ל אמרו (תו''כ) כי הוא אשר תקראו אותם, פירוש כי מועדי ה' הם בזמן שיקראו אותם ישראל. וצריך לדעת למה חזר לומר אלה הם מועדי. עוד צריך לדעת למה חזר לצוות על השבת. ועוד רואה אני שחזר לומר פעם שני אחר מצוות השבת אלה מועדי ה'. ונראה כי שיעור הכתובים הוא שמתחלה צוה ה' כי עיקר המועדות תלוי בזמנים אשר יקראו אותם, וחש הכתוב שיטעו לומר שבכלל זה גם כן קדושת יום השבת אם יסכימו לדחותו מיומו ליום אחר יתקדש על פיהם, לזה חזר ופירש **אלה הם מועדי ששת ימים** וגו' פירוש אלה שהם שבתות הם מועדי מועדים שקבע הבורא ואינם בגדר השתנות. וחזר לומר **אלה מועדי ה' מקראי קודש** אשר הרשיתי אתכם שתקראו אותם אתם בחודש הראשון וגו' פסח שבועות ראש השנה יום כיפור סוכות אלו אין קדושתם אלא על פי ישראל:
@59 **עוד** נראה לומר טעם שכפל לומר **אשר תקראו אותם** ב' פעמים, על דרך מה שכתב רמב''ם בפרק ד' מהלכות קידוש החודש וזה לשונו על שלשה סיבות מעברין השנה על התקופה ועל האביב ועל פירות האילן. ויש שם דברים אחרים שבית דין מעברין בשבילן מפני הדרכים וכו' ומפני הגשרים וכו' ומפני תנורי פסחים וכו' ומפני גליות ישראל שנעקרו ממקומן ועדיין לא הגיעו לירושלים וכו' ע''כ. הרי כי לב' סיבות כוללות מעברין ומאחרין המועד, הא' לצד תנאי הזמן שיהיה באביב, והב' לצד כשרון העם, לזה אמר הכתוב ב' פעמים אשר תקראו אותם, ושלא תאמר שלצד תנאי הזמן שהתנה הכתוב חודש האביב לבד מעברין אבל לכשרון העם יעשה המועד בזמנים הנמצאים מוכשרים, תלמוד לומר ב' פעמים **אשר תקראו אותם**:
@62 **בין הערבים פסח לה'** פירוש חלק הנוגע לה' מקרבן פסח שהוא מתן דמים והקטרת חלבים יהיה בין הערבים, אבל חלק הנוגע לישראל שהוא אכילת הבשר יהיה בליל ט''ו על מצות ומרורים. עוד ירצה באומרו **פסח לה'** לצד שפסח מצרים שהוא פסח ראשון עשוהו לאהבת הערב והמועיל, הערב שאמרו ז''ל (שמו''ר פי''ט) שנתבשם פסחו של משה מרוחות (מריח) גן עדן, ועיין מה שפירשתי בפרשת בא (יב מג), והמועיל לפסוח המשחית על בתיהם, וכאן אמר כי פסח דורות יעשוהו לשם ה' הגם שאין בו אחד משתיהן:
@72 **וספרתם לכם וגו'**. אומרו **לכם** לצד שיצו ה' לספור שבע שבתות, ואמרו ז''ל (זוהר ח''ג צד.) כי לצד שהיו בטומאת מצרים ורצה ה' להזדווג לאומה זו דן בה כמשפט נדה שדינה לספור ז' נקיים, וצוה שיספרו ז' שבועות ואז יהיו מוכשרים להכניסתם כלה לחופה, והגם כי שם ז' ימים וכאן ז' שבועות, לצד הפלגת הטומאה וגם היותם בכללות ישראל שיער התמים דעים כי כן משפטם, ועיין מה שפרשתי בפסוק (יתרו יט א) בחודש השלישי לצאת וגו', והוא מאמר הכתוב כאן **וספרתם לכם** פירוש סיבת ספירה זו היא לסיבתכם לטהרתכם שזולת זה תיכף היה ה' נותן להם התורה. ולדרך זה ידוייק על נכון טעם **ממחרת השבת** ולא מיום השבת עצמו, כי כן משפט הספירה שיהיו כל הימים שלימים, ולצד שיום ט''ו בניסן שהוא יום השבת האמור כאן מקצת היום היו עדיין בארץ מצרים לזה יצו ה' לספור ממחרת, והגם כי זה היה בפסח מצרים, כמשפט הזה יעשה באותו פרק עצמו מדי שנה בשנה, כי כמו כן יעשה בסוד ה' כידוע ליודעי חן. וכפי הפשט לזכרון העובר ביום השבת לזכרון כי ששת ימים וגו' והמשכיל יבין. ועיין מה שפרשתי בפרשת בראשית בפסוק ויכל אלהים ביום השביעי, ובדרך רמז רמז באומרו **וספרתם** על דרך אומרם ז''ל כי נשמות עם בני ישראל הם בבחינת הלוחות, ובאמצעות תחלואי הנפש וטומאת התיעוב יתלכלכו ויחשיך אורם, וארז''ל (ויק''ר פל''ב) כי הלוחות של סנפרינון היו. לזה אמר **וספרתם לכם** פירוש באמצעות מנין זה אתם מאירים כסנפרינון את עצמיכם:
@72 **ממחרת השבת מיום וגו'**. פירוש מעכשיו קודם שתכנסו לארץ ממחרת השבת, וכנגד אחר ביאתם לארץ אמר **מיום הביאכם** וגו', ולזה הקדים ממחרת השבת להיותה מצוה שישנה אז מה שאין כן מיום הביאכם שהוא אחר ביאה לארץ:
@72 **ובקצרכם את קציר וגו'**. מה ענין זה לכאן. ואולי שבא לחייב גם שדה שהובא ממנו העומר שחייב בלקט ופאה, שתבא הסברא לומר כיון שתחלתו נקצר לקרבן יהיה פטור מפאה וכו' תלמוד לומר. ולזה תמצא שלא הזכיר אלא לקט ופאה שהם חובת שדה בלא סובב אמצעי ולא הוזכר שכחה שהיא באה מצד בעל השדה, ות''ל בתורת כהנים אמרו שרמז ה' בזה שכל מי שנותן לקט שכחה ופאה מעלה עליו כאלו בית המקדש קיים והוא מקריב קרבנותיו לתוכו וכו' ע''כ. מה שאמר שכחה תגם שלא הוזכר בפסוק, לצד שהיא מצוה שחייב בה כלקט ופאה כללה. והכ' שלא כתב להעירך שנתכוין גם כן לדרך שכתבתי:
@84 **יוה'** ' **כ וגו' מקרא קודש וגו'** פירוש בלא אמצעות קריאתם אותו קודש ובלא עינוי שמתענים בו הוא יום כיפור מצד עצמו, ומעתה יש שכר למצות קריאת קודש ועינוי בו מלבד ריוח הכפרה:
@85 **וכל מלאכה וגו' כי יום כיפורים וגו'**. נתינת טעם זה הוא על דרך מה שאמרו בסוטה דף מ' שאין אומרים פסוקים כשהכהנים מברכין את העם והטעם אמרו וז''ל כלום יש עבד שמברכין אותו ואינו מאזין ע''כ, ולדרך זה אמר וכל מלאכה לא תעשו, והטעם כי יום כיפורים הוא פירוש כי עיצומו של יום מכפר ויש לך אדם שהזמן מכפר עליו והוא עסוק במלאכתו, והמשכיל על דבר עיצומו של יום לבבו יבין המכפר כי הוא אדון המאיר היום לסגל סגל דבר זה:
@91 **הזה חג הסוכות**. בתורת כהנים דרשו יתור הזה, ופירשתי הברייתא בפרשת מצורע (י''ד ז') (לז) **מועדי ה'**. אמר רבי עקיבא (תורת כהנים פסוק ל''ה) אלו ימי מועד שאסורין במלאכה ע''כ, ונראה כי לזה גמר אומר **ומלבד מתנותיכם** וגו' **כל נדריכם** וגו' **כל נדבותיכם** אשר תתנו לה' שמשמע אפילו עולות ואין עולות באין ביום טוב כאומרם (ביצה י''ט.) לכם ולא לגבוה אלא ודאי שאין הכתוב מדבר אלא בחולו של מועד:
@103 **צו את בני ישראל וגו** '. צריך לדעת מה ענין מצות שמן והדלקתו במקום זה, גם מצות מערכת השלחן מה ענינו לכאן, ומה גם שכבר נאמרו הדברים ככתבן במקומן במצות המשכן ומצותיו, ורש''י ז''ל פירש מה שפירש, ואין בדבריו דבר מספיק, ורמב''ן ז''ל כתב שכלה השמן וכו', ואין ראיה לדבריו, ואולי כי לצד שצוה מצות שבעיות פסח ז' ימים, חג הסוכות ז' ימים, שמחת המינים ז' ימים, גם ראש השנה ויום הכיפורים ישנם בבחינת השבע להיותם בחודש השביעי, לזה סמך לזה גם כן מצות המנורה שהיא בחינת שבע נרות, גם השלחן ישנו בסוד שבע דכתיב שש המערכת וגו' והשלחן הסדורות עליו שהוא סוד המתקבץ בו שש מעלות והיא משלמת שבע, ותמצא שצוה גם כן בפרשה זו מצות העומר שהוא שבע שבתות, גם מצות השבת, נמצאת אומר שכלל כל מצות השביעיות יחד לומר כי סודם ועיקרם אחד:
@103 **עוד** אפשר שנתכוין בסמיכות פרשת מנורה לפרשת סוכה על דרך מה שאמרו ז''ל (תורת כהנים) בפסוק מחוץ לפרוכת העדות וז''ל וכי לאורה היה צריך והלא כל המ' שנה שהיו במדבר לא הלכו אלא לאורו, ופירשו התוספות (שבת כ''ב:) שלא היו הולכים לאור החמה אלא לאור השכינה שהיו רואים מה שבתוך התפוח וכו' אלא עדות לבאי עולם וכו' ע''כ, והוא מה שנתחכם ה' בסמיכות זה של מצות המנורה למצות סוכה כי בסוכות וגו' לומר כי ישראל לצד ענני כבוד לא היה להם אור השמש והליכתם היתה לאורו יתברך, אם כן מצות מנורה אינה אלא לפרוכת העדות עדות לבאי עולם וכו':
@111 **ויצא בן אשה וגו'**. אמר **ויצא** על דרך אומרם ז''ל (תנחומא) בפסוק ויצא העגל הזה שיצא בלא כוונת הפועל, כמו כן כאן לא שנתכוונה האשה ישראלית למעשה הכיעור אלא בלא מתכוין לדבר איסור יצא הנגע, כאומרם ז''ל (שמו''ד פ''א) שהעמיד המצרי הבעל לעבודתו וחזר לבית ועשה מעשה והאשה חשבה כי בעלה היה ויצא נגע זה, ולזה תמצא שהכתוב משוה זכרון האשה לזכרון האיש הישראלי דכתיב **האשה הישראלית ואיש הישראלי** כי נקיה האשה מעון ושוה לאיש הישראלי המוזכר לפנינו שאין בו דופי, ואומרו **בתוך בני ישראל** לומר שלא היה בתוכם ממזר כיוצא בו:
@111 **עוד** ירצה שלא נתנו לו מושב בתוכם שבמקום שהיה רוצה לטעת אהלו היה אומר לו אינך משלנו, ורז''ל (תורת כהנים) אמרו שבא לומר הכתוב שנתגייר ואלו ואלו דברי אלהים חיים:
@111 **ואיש הישראלי**. טעם שלא הוזכר שמו, אולי שלא רצה להזכירו משום שעל ידו היה הדבר שנקב בן הישראלית את השם ומגלגלין וכו', ואין הקדוש ברוך הוא חפץ לגנות אדם, ומה גם בתורה שנשאר הרושם לעולם ועד:
@111 **עוד** נתכוין הכתוב לומר שמריבה אשר נצו עליה היא על הפרש הנרשם שזה הוא בן ישראלית וזה בן ישראלי וכאן כלל כל מה שאמרו ז''ל (ויק''ר פל''ב) למ''ד על דבר יוחסין ולמ''ד וכו', ולא חש הכתוב להאריך לשון ולומר גם כן שמו כי אין צורך בדבר:
@112 **ושם אמו**. צריך לדעת למה לא הזכיר שמה בתחלה כשהזכירו עד הבאתו אל משה, ויש לומר בב' דרכים, האחד לשבח על זה הדרך **ויביאו אותו אל משה ושם אמו** וגו', פירוש גם היא מכלל המביאים והאחד לגנאי ויביאו אותו אל משה ועל ידי הבאה זו נתחייבה שהכתוב יפרסם אותה שאמו היא שלומית, וממוצא דבר אתה יודע כי נכמרו רחמיה על בנה וכתיב (משלי י''ב) ורחמי רשעים אכזרי, לזה גילה אותה הכתוב כי זאת האשה וזה בנה, גם הזכיר שבטה להטעם עצמו שכתבתי כי מן הסתם השבט ירחם ויעמוד לעזר הקרובים, ולזה אמרו במדרש (ויק''ר פל''ב) גנאי לו גנאי לשבטו וכו':
@123 **כגר כאזרח**. ולא אמר הגר כאזרח, שאז יהיה נשמע כי מדרגת גר למטה ממדרגת אזרח שהקטן נתלה בגדול, לזה אמר **כגר כאזרח** פירוש האזרח כגר והגר כאזרח ששקולים הם במשפט:
@124 **ובני ישראל עשו וגו'**. קשה מה מקום ובני ישראל עשו וגו' אחר שאמר ויוציאו את המקלל וגו' וירגמו אותו אבן הריני רואה שעשו את אשר צוה ה', וי''ל לצד שהיה הדבר על ידי מריבה ומחלוקת שהיתה בין הישראלי ובין בן הישראלית יש מקום לומר שעשו בו משפט כתוב לאמצעות גם כן טינא שבלב, לזה אמר **עשו כאשר צוה ה'** פירוש לצד מצות ה' הוא שעשו:
@124 **או** נתכוין הכתוב להעלות המצוה שעשאוה כל ישראל הגם שלא היתה בו יד כולם:
@124 **או** ירצה שעל ידי מעשה זה שקנאו קנאת כבודו יתברך העלה עליהם הכתוב גם כן כאלו עשו כל התורה, והוא אומרו כאשר צוה ה' את משה בדרך כלל:
@124 **או** יאמר על זה הדרך לצד שבמצות ה' למשה אמר **הוצא את המקלל** שחוזר אל משה כי הוא יוציא אותו והרגימה תהיה על ידי ישראל דכתיב **ורגמו אותו כל העדה**, וכאן אמר ויוציאו המקלל שחוזר אל ישראל המוזכרים בסמוך, ובא הכתוב לשבח לישראל ואמר **ובני ישראל עשו כאשר צוה ה' למשה**, פירוש לעשות הוא קדמו הם בדברו אליהם ועשו אותו קודם שיעשהו משה לצד הזריזות והמהירות לקיים מצות ה', ולדרכים הראשונים נפרש הוצא, או הוא או שלוחו:
@124 **חסלת פרשת אמור**
